const STALE_DAYS = 7;
// Office location for GPS-gated check-in: someone can only check in when their
// browser reports a position within OFFICE_RADIUS_METERS of this point.
const OFFICE_LAT = 29.977104738544607;
const OFFICE_LNG = 30.99626765215839;
const OFFICE_RADIUS_METERS = 100;
function distanceMeters(lat1, lng1, lat2, lng2) {
  const R = 6371000;
  const toRad = (d) => (d * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}
function mapAttendance(row) {
  return { id: row.id, userId: row.user_id, checkedInAt: row.checked_in_at, lat: row.lat, lng: row.lng, distanceMeters: row.distance_meters };
}
const MS_DAY = 24 * 60 * 60 * 1000;

