    const shown = statusPick.length ? leads.filter((l) => statusPick.includes(l.status)).sort(byRecent) : (tabs.find((t) => t[0] === leadTab) || tabs[0])[2];
    const fbCounts = {}; leads.forEach((l) => { fbCounts[l.status] = (fbCounts[l.status] || 0) + 1; });
