              <div ref={moreLeadsRef} style={{ display: "flex", justifyContent: "center", padding: "10px 0" }}>
                <button onClick={() => setLeadLimit((n) => n + 30)} style={btnGhost}>Show more ({shown.length - leadLimit} left)</button>
              </div>
