// ---------- WhatsApp templates ----------
const DEFAULT_WA_TEMPLATES = [
  { id: "welcome", label: "Welcome", text: "Hi {first}, this is {sales} from Origin Real Estate. Thanks for your interest! When is a good time for a quick call?" },
  { id: "meeting", label: "Confirm meeting", text: "Hi {first}, just confirming our meeting on {meeting}. Looking forward to seeing you. — {sales}, Origin Real Estate" },
  { id: "after_units", label: "After sending units", text: "Hi {first}, did you get a chance to look at the units I sent? Happy to arrange a viewing whenever suits you. — {sales}" },
  { id: "no_answer", label: "Missed call", text: "Hi {first}, I tried calling you. Let me know a good time to talk. — {sales}, Origin Real Estate" },
  { id: "after_meeting", label: "After the meeting", text: "Hi {first}, thank you for your time today. As promised, I'll send you the details we discussed. Any question, I'm here. — {sales}, Origin Real Estate" },
  { id: "after_deal", label: "After the deal", text: "Congratulations {first} on your new home! It was a pleasure working with you. If you need anything at all, I'm always here. — {sales}, Origin Real Estate" },
  { id: "referral", label: "Ask for a referral", text: "Hi {first}, I hope you're enjoying your home! If any friend or family member is looking to buy, sell or rent in Zayed or October, I'd be happy to help them the same way. — {sales}, Origin Real Estate" },
];
function fillTemplate(text, client, salesName) {
  const meeting = client.meetingAt ? new Date(client.meetingAt).toLocaleString("en-GB", { weekday: "short", day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" }) : "—";
  const first = client.name && !/^[0-9+ ]+$/.test(client.name) ? client.name.split(" ")[0] : "";
  return String(text).replace(/\{first\}/g, first || "there").replace(/\{name\}/g, client.name || "").replace(/\{sales\}/g, salesName || "").replace(/\{meeting\}/g, meeting);
}
function WhatsAppTemplates({ client, templates, salesName, onSent }) {
  const list = Array.isArray(templates) && templates.length ? templates : DEFAULT_WA_TEMPLATES;
  if (!client.phone) return null;
  return (
    <div style={{ display: "flex", gap: 6, flexWrap: "wrap", alignItems: "center" }}>
      <span style={{ fontSize: 11.5, fontWeight: 800, color: COLORS.textMuted, letterSpacing: 0.3 }}>WHATSAPP</span>
      {list.map((t) => (
        <a key={t.id || t.label} className="chip" href={`https://wa.me/${waNumber(client.phone)}?text=${encodeURIComponent(fillTemplate(t.text, client, salesName))}`} target="_blank" rel="noreferrer"
          onClick={(e) => { e.preventDefault(); if (onSent) onSent(); openWa(client.phone, fillTemplate(t.text, client, salesName)); }}
          style={{ textDecoration: "none", fontSize: 12, fontWeight: 700, padding: "5px 11px", borderRadius: 999, background: "#E7F8EE", color: "#137A3F", border: "1px solid #BFE9CF" }}>{t.label}</a>
      ))}
    </div>
  );
}
function LateLeadSettings({ ctx }) {
  const { fin, act } = ctx;
  const [hours, setHours] = useState(String(fin.settings?.late_lead_hours ?? 2));
  const [auto, setAuto] = useState(!!fin.settings?.auto_reassign);
  const [saved, setSaved] = useState(false);
  const { busy, error, run } = useAction();
  return (
    <div style={finCard}>
      <div style={{ fontWeight: 600, fontSize: 14, color: COLORS.navy, marginBottom: 4 }}>Late leads</div>
      <div style={{ fontSize: 12, color: COLORS.textMuted, marginBottom: 8 }}>A new lead nobody contacted after this many hours → a phone alert to the sales person and their manager (9 AM – 10 PM).</div>
      <div style={{ display: "flex", gap: 10, alignItems: "flex-end", flexWrap: "wrap" }}>
        <Field label="Hours"><input inputMode="numeric" style={{ ...inputStyle, width: 90 }} value={hours} onChange={(e) => { setHours(e.target.value.replace(/\D/g, "")); setSaved(false); }} /></Field>
        <label style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 13, paddingBottom: 10 }}><input type="checkbox" checked={auto} onChange={(e) => { setAuto(e.target.checked); setSaved(false); }} /> Move it automatically to the least-busy sales person in the same team</label>
      </div>
      <button style={btnPrimary} disabled={busy} onClick={() => run(async () => { await act((t) => db.update("finance_settings", 1, { late_lead_hours: Math.max(1, Number(hours) || 2), auto_reassign: auto, updated_at: new Date().toISOString() }, t)); setSaved(true); })}>Save</button>
      {saved && <span style={{ marginLeft: 8, fontSize: 12.5, color: COLORS.success }}>Saved ✓</span>}
      {error && <div style={{ color: COLORS.danger, fontSize: 12.5, marginTop: 6 }}>{error}</div>}
    </div>
  );
}
const BACKUP_TABLES = ["profiles", "developers", "projects", "units", "unit_owners", "unit_sales", "clients", "client_activity", "client_units", "client_projects", "lead_duplicates", "deals", "deal_agents", "deal_rates",
  "finance_transactions", "finance_accounts", "expense_categories", "recurring_expenses", "staff_targets", "staff_salaries", "commission_rates", "finance_settings",
  "attendance", "cold_sheets", "cold_leads", "cold_activity", "campaign_spend", "share_links", "finance_audit"];
function saveBlob(blob, name) {
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob); a.download = name;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(a.href), 4000);
}
function BackupSettings({ ctx }) {
  const { act } = ctx;
  const [busy, setBusy] = useState(""), [msg, setMsg] = useState(""), [files, setFiles] = useState(null);
  const storage = (path, init, t) => fetch(`${SUPABASE_URL}/storage/v1/${path}`, { ...init, headers: { apikey: SUPABASE_ANON_KEY, Authorization: `Bearer ${t}`, "Content-Type": "application/json" } });
  const downloadNow = async () => {
    setBusy("now"); setMsg("");
    try {
      await act(async (t) => {
        const tables = {};
        for (const name of BACKUP_TABLES) { try { tables[name] = await db.selectAll(name, "", t); } catch (e) { tables[name] = []; } }
        const n = Object.values(tables).reduce((s, l) => s + (l || []).length, 0);
        saveBlob(new Blob([JSON.stringify({ made_at: new Date().toISOString(), tables }, null, 1)], { type: "application/json" }), `origin-crm-backup-${todayInput()}.json`);
        setMsg(`Downloaded ✓ · ${n.toLocaleString()} rows`);
      });
    } catch (e) { setMsg(e.message || "Could not make the backup"); }
    setBusy("");
  };
  const loadList = async () => {
    setBusy("list");
    try { await act(async (t) => { const r = await storage("object/list/backups", { method: "POST", body: JSON.stringify({ prefix: "", limit: 50, sortBy: { column: "name", order: "desc" } }) }, t); setFiles(r.ok ? (await r.json()).filter((f) => /^backup-/.test(f.name)) : []); }); }
    catch (e) { setFiles([]); }
    setBusy("");
  };
  const getFile = async (name) => {
    setBusy(name);
    try { await act(async (t) => { const r = await storage(`object/authenticated/backups/${name}`, { method: "GET" }, t); if (!r.ok) throw new Error("Could not download"); saveBlob(await r.blob(), name); }); }
    catch (e) { setMsg(e.message); }
    setBusy("");
  };
  return (
    <div style={finCard}>
      <div style={{ fontWeight: 600, fontSize: 14, color: COLORS.navy, marginBottom: 4 }}>Backup</div>
      <div style={{ fontSize: 12, color: COLORS.textMuted, marginBottom: 8 }}>A full copy of the data is saved automatically every Sunday at 3 AM (the last 8 weeks are kept). You can also download one now.</div>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
        <button style={btnPrimary} disabled={!!busy} onClick={downloadNow}>{busy === "now" ? "Preparing…" : "⬇ Download backup now"}</button>
        <button style={{ ...btnPrimary, background: "#fff", color: COLORS.navy, border: `1px solid ${COLORS.border}` }} disabled={!!busy} onClick={loadList}>{busy === "list" ? "Loading…" : "Weekly backups"}</button>
      </div>
      {msg && <div style={{ fontSize: 12.5, marginTop: 6, color: /✓/.test(msg) ? COLORS.success : COLORS.danger }}>{msg}</div>}
      {files && (
        <div style={{ marginTop: 8, display: "flex", flexDirection: "column", gap: 4 }}>
          {files.length === 0 ? <div style={{ fontSize: 12.5, color: COLORS.textMuted }}>No weekly backups yet — the first one runs on Sunday.</div> : files.map((f) => (
            <button key={f.name} disabled={!!busy} onClick={() => getFile(f.name)} style={{ textAlign: "left", border: `1px solid ${COLORS.border}`, background: "#fff", borderRadius: 10, padding: "6px 10px", fontSize: 12.5, cursor: "pointer" }}>
              {busy === f.name ? "Downloading…" : `⬇ ${f.name}`}{f.metadata?.size ? ` · ${(f.metadata.size / 1048576).toFixed(1)} MB` : ""}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

function ColdTemplateSettings({ ctx }) {
  const { fin, act } = ctx;
  const [text, setText] = useState(fin.settings?.wa_cold_template || DEFAULT_COLD_WA);
  const [textEn, setTextEn] = useState(fin.settings?.wa_cold_en || DEFAULT_COLD_WA_EN);
  const [saved, setSaved] = useState(false);
  const { busy, error, run } = useAction();
  return (
    <div style={{ ...finCard, gridColumn: "1 / -1" }}>
      <div style={{ fontWeight: 600, fontSize: 14, color: COLORS.navy, marginBottom: 4 }}>Cold call WhatsApp messages (Arabic / English)</div>
      <div style={{ fontSize: 12, color: COLORS.textMuted, marginBottom: 8 }}>{"{greeting}"} becomes صباح الخير before 12 and مساء الخير after · {"{sales}"} the sales person · {"{in_project}"} " في" + the project (empty if no project) · {"{project}"} · {"{owner}"} · {"{unit}"}</div>
      <textarea dir="auto" rows={3} style={{ ...inputStyle, resize: "vertical" }} value={text} onChange={(e) => setText(e.target.value)} />
      <div style={{ fontSize: 12, color: COLORS.textMuted, margin: "6px 0" }}>Preview: <span dir="auto">{coldWaText(text, { project_name: "Westown", owner_name: "Ahmed", unit_number: "B-12" }, ctx.profile?.name || "Omar")}</span></div>
      <div style={{ fontSize: 12, fontWeight: 600, color: COLORS.navy, marginTop: 6 }}>English</div>
      <textarea dir="ltr" rows={3} style={{ ...inputStyle, resize: "vertical" }} value={textEn} onChange={(e) => setTextEn(e.target.value)} />
      <div style={{ fontSize: 12, color: COLORS.textMuted, margin: "6px 0" }}>Preview: {coldWaText(textEn, { project_name: "Westown", owner_name: "Ahmed", unit_number: "B-12" }, ctx.profile?.name || "Omar", "en")}</div>
      <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
        <button style={btnPrimary} disabled={busy} onClick={() => run(async () => { setSaved(false); await act((tk) => db.update("finance_settings", 1, { wa_cold_template: text.trim() || null, wa_cold_en: textEn.trim() || null, updated_at: new Date().toISOString() }, tk)); setSaved(true); })}>Save message</button>
        <button style={btnGhost} onClick={() => { setText(DEFAULT_COLD_WA); setTextEn(DEFAULT_COLD_WA_EN); }}>Reset</button>
        {saved && <span style={{ color: COLORS.success, fontSize: 12.5 }}>Saved ✓</span>}
      </div>
      <FinError text={error} />
    </div>
  );
}

function OwnerAskSettings({ ctx }) {
  const { fin, act } = ctx;
  const [ar, setAr] = useState(fin.settings?.wa_owner_ar || DEFAULT_OWNER_AR);
  const [en, setEn] = useState(fin.settings?.wa_owner_en || DEFAULT_OWNER_EN);
  const [saved, setSaved] = useState(false);
  const { busy, error, run } = useAction();
  const sample = { ownerName: "Ahmed", unitNumber: "B-12", type: "Apartment", listingType: "sale" };
  return (
    <div style={{ ...finCard, gridColumn: "1 / -1" }}>
      <div style={{ fontWeight: 600, fontSize: 14, color: COLORS.navy, marginBottom: 4 }}>Owner WhatsApp — "is the unit still available?"</div>
      <div style={{ fontSize: 12, color: COLORS.textMuted, marginBottom: 8 }}>The sales person picks Arabic or English from the unit and can still edit the text before sending. {"{greeting}"} · {"{owner}"} · {"{sales}"} · {"{type}"} · {"{unit}"} · {"{project}"} · {"{listing}"} (for sale / for rent)</div>
      <div style={{ fontSize: 12, fontWeight: 600, color: COLORS.navy }}>Arabic</div>
      <textarea dir="rtl" rows={3} style={{ ...inputStyle, resize: "vertical" }} value={ar} onChange={(e) => setAr(e.target.value)} />
      <div style={{ fontSize: 12, color: COLORS.textMuted, margin: "4px 0 10px" }} dir="rtl">{ownerAskText(ar, "ar", sample, "Westown", ctx.profile?.name || "Omar")}</div>
      <div style={{ fontSize: 12, fontWeight: 600, color: COLORS.navy }}>English</div>
      <textarea dir="ltr" rows={3} style={{ ...inputStyle, resize: "vertical" }} value={en} onChange={(e) => setEn(e.target.value)} />
      <div style={{ fontSize: 12, color: COLORS.textMuted, margin: "4px 0 10px" }}>{ownerAskText(en, "en", sample, "Westown", ctx.profile?.name || "Omar")}</div>
      <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
        <button style={btnPrimary} disabled={busy} onClick={() => run(async () => { setSaved(false); await act((tk) => db.update("finance_settings", 1, { wa_owner_ar: ar.trim() || null, wa_owner_en: en.trim() || null, updated_at: new Date().toISOString() }, tk)); setSaved(true); })}>Save messages</button>
        <button style={btnGhost} onClick={() => { setAr(DEFAULT_OWNER_AR); setEn(DEFAULT_OWNER_EN); }}>Reset</button>
        {saved && <span style={{ color: COLORS.success, fontSize: 12.5 }}>Saved ✓</span>}
      </div>
      <FinError text={error} />
    </div>
  );
}

function WaTemplatesSettings({ ctx }) {
  const { fin, act } = ctx;
  const [list, setList] = useState(() => (Array.isArray(fin.settings?.wa_templates) && fin.settings.wa_templates.length ? fin.settings.wa_templates : DEFAULT_WA_TEMPLATES));
  const [saved, setSaved] = useState(false);
  const { busy, error, run } = useAction();
  const upd = (i, k, v) => setList((l) => l.map((x, j) => (j === i ? { ...x, [k]: v } : x)));
  return (
    <div style={{ ...finCard, gridColumn: "1 / -1" }}>
      <div style={{ fontWeight: 600, fontSize: 14, color: COLORS.navy, marginBottom: 4 }}>WhatsApp templates</div>
      <div style={{ fontSize: 12, color: COLORS.textMuted, marginBottom: 10 }}>One tap from the client page. Use {"{first}"} for the client's first name, {"{name}"} full name, {"{sales}"} the sales person, {"{meeting}"} the meeting time.</div>
      {list.map((t, i) => (
        <div key={i} style={{ display: "flex", gap: 8, marginBottom: 8, alignItems: "flex-start", flexWrap: "wrap" }}>
          <input style={{ ...inputStyle, width: 170, padding: "6px 8px" }} value={t.label} onChange={(e) => upd(i, "label", e.target.value)} placeholder="Button name" />
          <textarea rows={2} style={{ ...inputStyle, flex: "1 1 280px", padding: "6px 8px", resize: "vertical" }} value={t.text} onChange={(e) => upd(i, "text", e.target.value)} />
          <button onClick={() => setList((l) => l.filter((_, j) => j !== i))} style={{ border: "none", background: "none", color: COLORS.danger, cursor: "pointer" }} aria-label="Remove"><X size={16} /></button>
        </div>
      ))}
      <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
        <button style={btnGhost} onClick={() => setList((l) => [...l, { id: `t${Date.now()}`, label: "New message", text: "Hi {first}, " }])}>+ Add template</button>
        <button style={btnPrimary} disabled={busy} onClick={() => run(async () => {
          setSaved(false);
          const clean = list.filter((t) => t.label.trim() && t.text.trim()).map((t, i) => ({ id: t.id || `t${i}`, label: t.label.trim(), text: t.text.trim() }));
          await act((tk) => db.update("finance_settings", 1, { wa_templates: clean, updated_at: new Date().toISOString() }, tk));
          setSaved(true);
        })}>Save templates</button>
        {saved && <span style={{ color: COLORS.success, fontSize: 12.5 }}>Saved ✓</span>}
      </div>
      <FinError text={error} />
    </div>
  );
}

// Admin / CEO: change any field of a client
const isoToLocalInput = (iso) => { if (!iso) return ""; const d = new Date(iso); if (isNaN(d)) return ""; return new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 16); };
function ClientEditModal({ client, users, onSave, onClose }) {
  const [f, setF] = useState(() => ({
    name: client.name || "", phone: client.phone || "", email: client.email || "", source: client.source || "", referralName: client.referralName || "",
    campaign: client.campaign || "", budget: client.budget ?? "", interest: client.interest || "buy", notes: client.notes || "", assignedTo: client.assignedTo || "",
    stage: client.stage || "new_lead", meetingAt: isoToLocalInput(client.meetingAt), nextAction: client.nextAction || "", nextActionAt: isoToLocalInput(client.nextActionAt),
    createdAt: (client.createdAt || "").slice(0, 10),
  }));
  const set = (k) => (e) => { const v = e && e.target ? e.target.value : e; setF((x) => ({ ...x, [k]: v })); };
  const { busy, error, run } = useAction();
  const people = users.filter((u) => !["pending"].includes(u.role));
  const save = () => run(async () => {
    if (!f.name.trim()) throw new Error("Enter the client name.");
    if (!f.phone.trim()) throw new Error("Enter the phone number.");
    const patch = {
      name: f.name.trim(), phone: cleanPhone(f.phone), email: f.email.trim() || null, source: f.source || null,
      referral_name: f.source === "colleague_referral" ? (f.referralName.trim() || null) : null,
      campaign: f.campaign.trim() || null, budget: f.budget === "" ? null : f.budget, interest: f.interest, notes: f.notes.trim() || null,
      assigned_to: f.assignedTo || client.assignedTo, meeting_at: f.meetingAt ? new Date(f.meetingAt).toISOString() : null,
      next_action: f.nextAction.trim() || null, next_action_at: f.nextActionAt ? new Date(f.nextActionAt).toISOString() : null,
    };
    if (f.stage !== client.stage) { patch.stage = f.stage; patch.previous_stage = client.stage; }
    if (f.createdAt && f.createdAt !== (client.createdAt || "").slice(0, 10)) patch.created_at = new Date(`${f.createdAt}T12:00:00`).toISOString();
    await onSave(client, patch);
    onClose();
  });
  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(15,31,42,.45)", zIndex: 300, display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }} onClick={onClose}>
      <div className="card" style={{ background: "#fff", borderRadius: 16, padding: 18, width: "min(640px, 100%)", maxHeight: "90vh", overflow: "auto" }} onClick={(e) => e.stopPropagation()}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
          <div style={{ fontWeight: 800, color: COLORS.navy }}>Edit client</div>
          <button onClick={onClose} aria-label="Close" style={{ border: "none", background: "none", cursor: "pointer", color: COLORS.textMuted }}><X size={18} /></button>
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))", gap: 10 }}>
          <Field label="Name" required><input style={inputStyle} value={f.name} onChange={set("name")} /></Field>
          <Field label="Phone" required><input style={inputStyle} value={f.phone} onChange={set("phone")} inputMode="tel" /></Field>
          <Field label="Email"><input style={inputStyle} value={f.email} onChange={set("email")} /></Field>
          <Field label="Sales">
            <Sel style={{ ...inputStyle, appearance: "none" }} value={f.assignedTo} onChange={set("assignedTo")}>
              {people.map((u) => <option key={u.id} value={u.id}>{u.name}</option>)}
            </Sel>
          </Field>
          <Field label="Source">
            <Sel style={{ ...inputStyle, appearance: "none" }} value={f.source} onChange={set("source")}>
              <option value="">—</option>
              {SOURCES.map((x) => <option key={x.id} value={x.id}>{x.label}</option>)}
            </Sel>
          </Field>
          {f.source === "colleague_referral" && <Field label="Referred by"><input style={inputStyle} value={f.referralName} onChange={set("referralName")} /></Field>}
          <Field label="Campaign"><input style={inputStyle} value={f.campaign} onChange={set("campaign")} /></Field>
          <Field label="Looking to">
            <Sel style={{ ...inputStyle, appearance: "none" }} value={f.interest} onChange={set("interest")}>
              <option value="buy">Buy</option><option value="rent">Rent</option>
            </Sel>
          </Field>
          <Field label={f.interest === "rent" ? "Budget (rent / month)" : "Budget"}><MoneyInput value={f.budget} onChange={set("budget")} /></Field>
          <Field label="Stage">
            <Sel style={{ ...inputStyle, appearance: "none" }} value={f.stage} onChange={set("stage")}>
              {STAGES.map((x) => <option key={x.id} value={x.id}>{x.label}</option>)}
            </Sel>
          </Field>
          <Field label="Meeting"><input type="datetime-local" style={inputStyle} value={f.meetingAt} onChange={set("meetingAt")} /></Field>
          <Field label="Next follow-up"><input style={inputStyle} value={f.nextAction} onChange={set("nextAction")} /></Field>
          <Field label="Follow-up on"><input type="datetime-local" style={inputStyle} value={f.nextActionAt} onChange={set("nextActionAt")} /></Field>
          <Field label="Added on"><input type="date" style={inputStyle} value={f.createdAt} onChange={set("createdAt")} /></Field>
        </div>
        <div style={{ marginTop: 10 }}><Field label="Notes"><textarea style={{ ...inputStyle, minHeight: 70, resize: "vertical" }} value={f.notes} onChange={set("notes")} /></Field></div>
        <FinError text={error} />
        <div style={{ display: "flex", gap: 8, justifyContent: "flex-end", marginTop: 12 }}>
          <button style={btnGhost} onClick={onClose}>Cancel</button>
          <button style={btnPrimary} disabled={busy} onClick={save}>{busy ? "Saving…" : "Save changes"}</button>
        </div>
      </div>
    </div>
  );
}

function ClientProfile({ client, activity, assignedUser, projects, units, developers, projectInfoFn, linkedUnitIds, canManage, onEditClient, onBack, onChangeStage, onAddFeedback, onCloseLead, onRestore, onToggleUnitLink, onOpenUnit, onMarkSold, onChangeInterest, onQuickReply, onContact, matchSlot, waTemplates, salesName, getToken, onVoiceSaved }) {
  const [unitPickerOpen, setUnitPickerOpen] = useState(false);
  const timeline = activity.filter((a) => a.clientId === client.id).sort((a, b) => new Date(b.changedAt) - new Date(a.changedAt));

  const shareOnWhatsApp = () => {
    const lastNote = timeline.find((a) => a.note)?.note || "";
    const lines = [
      `Client: ${client.name}`,
      `Phone: ${client.phone}`,
      `Stage: ${STAGE_LABEL[client.stage]}`,
      lastNote ? `Last update: ${lastNote}` : "",
    ].filter(Boolean);
    openWa("", lines.join("\n"));
  };

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
      <button onClick={onBack} style={{ alignSelf: "flex-start", border: "none", background: "none", color: COLORS.navy, cursor: "pointer", fontSize: 13, fontWeight: 600 }}>&larr; Back to clients</button>

      <div style={{ background: "#fff", border: `1px solid ${COLORS.border}`, borderRadius: 16, padding: 18, display: "flex", flexDirection: "column", gap: 10 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", flexWrap: "wrap", gap: 8 }}>
          <div>
            <div style={{ fontWeight: 700, fontSize: 17, color: COLORS.navy }}>{client.name}</div>
            <div style={{ fontSize: 12.5, color: COLORS.textMuted, marginTop: 2, display: "flex", alignItems: "center", gap: 4 }}>{client.phone}{client.email ? ` · ${client.email}` : ""}<ContactButtons phone={client.phone} size={15} onContact={(kind) => onContact && onContact(client, kind)} /></div>
          </div>
          <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
            {onEditClient && <button onClick={onEditClient} style={{ ...btnGhost, padding: "4px 12px", fontSize: 12 }}>✎ Edit</button>}
            {client.qualified && <Badge tone="active">Qualified</Badge>}
            <ClientStageBadge stage={client.stage} />
          </div>
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(160px, 1fr))", gap: 10, fontSize: 12.5, color: COLORS.text }}>
          <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
            <b>Looking to:</b>
            {canManage && onChangeInterest ? (
              <Sel value={client.interest} onChange={(e) => onChangeInterest(e.target.value)} style={{ ...inputStyle, width: "auto", padding: "3px 8px", fontSize: 12.5, appearance: "none" }}>
                <option value="buy">Buy</option>
                <option value="rent">Rent</option>
              </Sel>
            ) : (client.interest === "rent" ? "Rent" : "Buy")}
          </div>
          {client.budget != null && client.budget !== "" && <div><b>Budget:</b> {client.interest === "rent" ? rentMoney(client.budget) : money(client.budget)}</div>}
          {client.source && <div><b>Source:</b> {SOURCE_LABEL[client.source]}{client.source === "colleague_referral" && client.referralName ? ` — ${client.referralName}` : ""}</div>}
          {assignedUser && <div><b>Sales:</b> {assignedUser.name} ({assignedUser.phone})</div>}
          <div><b>Added:</b> {formatDate(client.createdAt)}</div>
          <div><b>Last update:</b> {formatDate(clientLastActivityAt(client, activity))}</div>
          {client.meetingAt && <div><b>Meeting:</b> {formatDateTime(client.meetingAt)}</div>}
          {client.nextAction && !client.nextActionDone && (
            <div style={{ color: client.nextActionAt && new Date(client.nextActionAt) < new Date() ? COLORS.danger : COLORS.text }}>
              <b>Next follow-up:</b> {client.nextAction} · {timeUntil(client.nextActionAt)}
            </div>
          )}
          {client.stage === "closed" && <div><b>Closed reason:</b> {client.closedReason === "other" ? client.closedNote : CLOSE_REASON_LABEL[client.closedReason]}</div>}
        </div>
        {client.notes && <div style={{ fontSize: 12.5, color: COLORS.text, background: COLORS.cream, padding: 10, borderRadius: 10 }}>{client.notes}</div>}

        {canManage && onQuickReply && !["closed", "deal_done"].includes(client.stage) && (
          <div style={{ background: COLORS.cream, borderRadius: 16, padding: 12 }}>
            <div style={{ fontSize: 12, fontWeight: 700, color: COLORS.navy, marginBottom: 8 }}>Quick update</div>
            <QuickReplyBar client={client} activity={activity} onQuickReply={onQuickReply} onCloseLead={() => onCloseLead()} />
            <div style={{ marginTop: 10 }}><WhatsAppTemplates client={client} templates={waTemplates} salesName={salesName} onSent={() => onContact && onContact(client, "whatsapp")} /></div>
            {getToken && onVoiceSaved && <div style={{ marginTop: 10 }}><VoiceNoteRecorder client={client} getToken={getToken} onSaved={(path, secs) => onVoiceSaved(client, path, secs)} /></div>}
          </div>
        )}

        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginTop: 4 }}>
          {client.stage !== "closed" && (
            <>
              <button onClick={onChangeStage} style={{ background: COLORS.navy, color: "#fff", border: "none", padding: "8px 14px", borderRadius: 10, cursor: "pointer", fontSize: 12.5 }}>Change stage</button>
              {canManage && onMarkSold && client.stage !== "deal_done" && (
                <button onClick={onMarkSold} style={{ background: COLORS.success, color: "#fff", border: "none", padding: "8px 14px", borderRadius: 10, cursor: "pointer", fontSize: 12.5, fontWeight: 600 }}>{client.interest === "rent" ? "Mark as rented" : "Mark as sold"}</button>
              )}
              <button onClick={onAddFeedback} style={{ border: `1px solid ${COLORS.border}`, background: "#fff", color: COLORS.text, padding: "8px 14px", borderRadius: 10, cursor: "pointer", fontSize: 12.5 }}>Add feedback</button>
              {canManage && <button onClick={() => setUnitPickerOpen(true)} style={{ border: `1px solid ${COLORS.border}`, background: "#fff", color: COLORS.text, padding: "8px 14px", borderRadius: 10, cursor: "pointer", fontSize: 12.5 }}>Link units</button>}
              <button onClick={onCloseLead} style={{ border: `1px solid ${COLORS.danger}`, background: "#fff", color: COLORS.danger, padding: "8px 14px", borderRadius: 10, cursor: "pointer", fontSize: 12.5 }}>Remove lead</button>
            </>
          )}
          {client.stage === "closed" && (
            <button onClick={onRestore} style={{ background: COLORS.success, color: "#fff", border: "none", padding: "8px 14px", borderRadius: 10, cursor: "pointer", fontSize: 12.5 }}>Restore lead</button>
          )}
          <button onClick={shareOnWhatsApp} style={{ border: "none", background: "#25D366", color: "#fff", padding: "8px 14px", borderRadius: 10, cursor: "pointer", fontSize: 12.5 }}>Share on WhatsApp</button>
        </div>

        {linkedUnitIds.length > 0 && (
          <div style={{ fontSize: 12.5, color: COLORS.text, display: "flex", flexWrap: "wrap", gap: 6, marginTop: 4 }}>
            {linkedUnitIds.map((uid) => {
              const u = units.find((uu) => uu.id === uid);
              if (!u) return null;
              return (
                <button key={uid} onClick={() => onOpenUnit(u)} style={{ border: `1px solid ${COLORS.border}`, background: COLORS.creamDark, color: COLORS.text, fontSize: 11, fontWeight: 600, padding: "3px 9px", borderRadius: 20, cursor: "pointer" }}>
                  Unit {u.unitNumber}
                </button>
              );
            })}
          </div>
        )}

        {unitPickerOpen && (
          <UnitPicker
            units={units}
            developers={developers}
            projects={projects}
            projectInfoFn={projectInfoFn}
            linkedUnitIds={linkedUnitIds}
            onToggle={onToggleUnitLink}
            onClose={() => setUnitPickerOpen(false)}
          />
        )}
      </div>

      {matchSlot}

      <div style={{ background: "#fff", border: `1px solid ${COLORS.border}`, borderRadius: 16, padding: 18 }}>
        <div style={{ fontWeight: 600, fontSize: 14, color: COLORS.navy, marginBottom: 12 }}>Timeline</div>
        {timeline.length === 0 ? (
          <div style={{ fontSize: 12.5, color: COLORS.textMuted }}>No activity yet.</div>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            {timeline.map((a) => (
              <div key={a.id} style={{ display: "flex", gap: 10, fontSize: 12.5 }}>
                <Clock size={13} style={{ marginTop: 2, color: COLORS.textMuted, flexShrink: 0 }} />
                <div>
                  <div style={{ color: COLORS.textMuted, fontSize: 11.5 }}>{formatDateTime(a.changedAt)}</div>
                  <div style={{ color: COLORS.text }}>
                    {a.action === "stage_change" && <span><b>{STAGE_LABEL[a.oldValue] || a.oldValue}</b> → <b>{STAGE_LABEL[a.newValue] || a.newValue}</b></span>}
                    {a.action === "created" && <span>Client created</span>}
                    {a.action === "closed" && <span>Lead removed</span>}
                    {a.action === "project_link" && <span>Linked to project: {a.newValue}</span>}
                    {a.action === "unit_link" && <span>Linked to unit: {a.newValue}</span>}
                    {a.action === "call" && <span>Called</span>}
                    {a.action === "whatsapp" && <span>WhatsApp chat</span>}
                    {a.action === "unit_sent" && <span>Sent unit on WhatsApp: {a.newValue}</span>}
                    {a.action === "link_opened" && <span>👀 Opened the link you sent</span>}
                    {a.action === "liked_unit" && <span>❤️ Interested</span>}
                    {a.action === "voice" && <VoiceNotePlayer path={a.newValue} getToken={getToken} />}
                    {a.note && <div style={{ marginTop: 2, color: COLORS.text }}>{a.note}</div>}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

function UnitPicker({ units, developers, projects, projectInfoFn, linkedUnitIds, onToggle, onClose }) {
  const [f, setF] = useState({ destination: "", developerId: "", projectId: "", type: "", unitNumber: "" });

  const filtered = units.filter((u) => {
    const info = projectInfoFn(u);
    if (f.destination && info.destination !== f.destination) return false;
    if (f.developerId && info.developerId !== f.developerId) return false;
    if (f.projectId && u.projectId !== f.projectId) return false;
    if (f.type && u.type !== f.type) return false;
    if (f.unitNumber && !u.unitNumber.toLowerCase().includes(f.unitNumber.toLowerCase())) return false;
    return u.status !== "pending_delete";
  }).slice(0, 60);

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.45)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 100, padding: 16 }}>
      <div style={{ background: "#fff", borderRadius: 16, padding: 20, width: "100%", maxWidth: 900, maxHeight: "90vh", overflowY: "auto", display: "flex", flexDirection: "column", gap: 14 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <div style={{ fontWeight: 700, fontSize: 15, color: COLORS.navy }}>Pick interested units</div>
          <button onClick={onClose} style={{ border: "none", background: "none", cursor: "pointer" }}><X size={18} /></button>
        </div>

        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(150px, 1fr))", gap: 10 }}>
          <Select value={f.destination} onChange={(v) => setF((x) => ({ ...x, destination: v, projectId: "" }))} options={DESTINATIONS} placeholder="Destination" />
          <Sel value={f.developerId} onChange={(e) => setF((x) => ({ ...x, developerId: e.target.value, projectId: "" }))} style={{ ...inputStyle, appearance: "none" }}>
            <option value="">Developer</option>
            {developers.map((d) => <option key={d.id} value={d.id}>{d.name}</option>)}
          </Sel>
          <Sel value={f.projectId} onChange={(e) => setF((x) => ({ ...x, projectId: e.target.value }))} style={{ ...inputStyle, appearance: "none" }}>
            <option value="">Project</option>
            {projects.filter((p) => (!f.destination || p.destination === f.destination) && (!f.developerId || p.developerId === f.developerId)).map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}
          </Sel>
          <Select value={f.type} onChange={(v) => setF((x) => ({ ...x, type: v }))} options={TYPES} placeholder="Type" />
          <input style={inputStyle} placeholder="Unit number" value={f.unitNumber} onChange={(e) => setF((x) => ({ ...x, unitNumber: e.target.value }))} />
        </div>

        <div style={{ fontSize: 12, color: COLORS.textMuted }}>{filtered.length} unit{filtered.length !== 1 ? "s" : ""} shown{filtered.length === 60 ? " (narrow the filters for more)" : ""}</div>

        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))", gap: 14 }}>
          {filtered.map((u) => {
            const linked = linkedUnitIds.includes(u.id);
            return (
              <div key={u.id} style={{ position: "relative", border: linked ? `2px solid ${COLORS.success}` : "2px solid transparent", borderRadius: 16 }}>
                {linked && (
                  <div style={{ position: "absolute", top: 6, right: 6, zIndex: 5, background: COLORS.success, color: "#fff", borderRadius: "50%", width: 22, height: 22, display: "flex", alignItems: "center", justifyContent: "center" }}>
                    <Check size={13} />
                  </div>
                )}
                <UnitCard unit={u} projectInfo={projectInfoFn(u)} canSeeOwner={false} handledBy={null} onOpen={() => onToggle(u.id)} />
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

function ClientRow({ client, assignedUser, linkedUnits, notifCount, lastActivityAt, lastActionLabel, onOpen, onOpenUnit }) {
  return (
    <tr onClick={onOpen} style={{ cursor: "pointer", borderBottom: `1px solid ${COLORS.border}` }}>
      <td style={{ padding: "10px 12px" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <div style={{ width: 26, height: 26, borderRadius: "50%", background: COLORS.navy, color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 10.5, fontWeight: 700, flexShrink: 0 }}>
            {initials(client.name)}
          </div>
          <div>
            <div style={{ fontWeight: 600, fontSize: 13, color: COLORS.navy }}>{client.name}</div>
            <div style={{ display: "flex", gap: 5, marginTop: 2 }}>
              <ClientStageBadge stage={client.stage} />
              {client.qualified && <Badge tone="active">Qualified</Badge>}
              {notifCount > 0 && <span style={{ background: COLORS.danger, color: "#fff", fontSize: 10, fontWeight: 700, borderRadius: 20, padding: "1px 6px" }}>{notifCount}</span>}
            </div>
          </div>
        </div>
      </td>
      <td style={{ padding: "10px 12px", fontSize: 12.5, color: COLORS.text, whiteSpace: "nowrap" }} onClick={(e) => e.stopPropagation()}>
        {client.phone}<ContactButtons phone={client.phone} />
      </td>
      <td style={{ padding: "10px 12px", fontSize: 12, color: COLORS.textMuted, maxWidth: 220 }}>
        <div style={{ color: COLORS.text }}>{lastActionLabel || "—"}</div>
        <div style={{ fontSize: 11 }}>{timeAgo(lastActivityAt)}</div>
      </td>
      <td style={{ padding: "10px 12px", fontSize: 12 }} onClick={(e) => e.stopPropagation()}>
        {linkedUnits.length === 0 ? (
          <span style={{ color: COLORS.textMuted }}>—</span>
        ) : (
          <div style={{ display: "flex", flexWrap: "wrap", gap: 4 }}>
            {linkedUnits.map((u) => (
              <button key={u.id} onClick={() => onOpenUnit(u)} style={{ border: `1px solid ${COLORS.border}`, background: COLORS.creamDark, color: COLORS.text, fontSize: 10.5, fontWeight: 600, padding: "2px 8px", borderRadius: 20, cursor: "pointer" }}>
                {u.unitNumber}
              </button>
            ))}
          </div>
        )}
      </td>
    </tr>
  );
}

// ---------- Filters: one look and one behaviour on every screen ----------
const DATE_PRESETS = [
  ["", "Any time"], ["today", "Today"], ["yesterday", "Yesterday"], ["7d", "Last 7 days"], ["week", "This week"],
  ["month", "This month"], ["lastmonth", "Last month"], ["30d", "Last 30 days"], ["quarter", "This quarter"],
  ["lastquarter", "Last quarter"], ["year", "This year"], ["lastyear", "Last year"], ["custom", "Custom dates"],
];
const DATE_PRESET_LABEL = Object.fromEntries(DATE_PRESETS);
// Returns [from, to) for a date filter value { p, from, to }, or null for "any time"
function dateRangeOf(v) {
  if (!v || !v.p) return null;
  const now = new Date();
  const d0 = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const day = (n) => new Date(d0.getTime() + n * MS_DAY);
  switch (v.p) {
    case "today": return [d0, day(1)];
    case "yesterday": return [day(-1), d0];
    case "7d": return [day(-6), day(1)];
    case "30d": return [day(-29), day(1)];
    case "week": { const back = (d0.getDay() + 1) % 7; return [day(-back), day(7 - back)]; } // week starts Saturday
    case "month": return [new Date(now.getFullYear(), now.getMonth(), 1), new Date(now.getFullYear(), now.getMonth() + 1, 1)];
    case "lastmonth": return [new Date(now.getFullYear(), now.getMonth() - 1, 1), new Date(now.getFullYear(), now.getMonth(), 1)];
    case "quarter": { const q = Math.floor(now.getMonth() / 3) * 3; return [new Date(now.getFullYear(), q, 1), new Date(now.getFullYear(), q + 3, 1)]; }
    case "lastquarter": { const q = Math.floor(now.getMonth() / 3) * 3; return [new Date(now.getFullYear(), q - 3, 1), new Date(now.getFullYear(), q, 1)]; }
    case "year": return [new Date(now.getFullYear(), 0, 1), new Date(now.getFullYear() + 1, 0, 1)];
    case "lastyear": return [new Date(now.getFullYear() - 1, 0, 1), new Date(now.getFullYear(), 0, 1)];
    case "custom": {
      const f = v.from ? new Date(`${v.from}T00:00:00`) : new Date(2000, 0, 1);
      const t = v.to ? new Date(new Date(`${v.to}T00:00:00`).getTime() + MS_DAY) : new Date(2100, 0, 1);
      return [f, t];
    }
    default: return null;
  }
}
function inDate(iso, v) {
  const r = dateRangeOf(v);
  if (!r) return true;
  if (!iso) return false;
  const d = new Date(String(iso).length === 10 ? `${iso}T12:00:00` : iso);
  return d >= r[0] && d < r[1];
}
// "5m" → 5,000,000 · "500k" → 500,000 · "1,250,000" → 1250000
function parseAmount(s) {
  if (s === null || s === undefined) return null;
  const t = String(s).trim().toLowerCase().replace(/,/g, "").replace(/\s/g, "");
  if (!t) return null;
  const m = t.match(/^(-?\d*\.?\d+)\s*(k|m|mn|million|b)?$/);
  if (!m) return null;
  const mult = { k: 1e3, m: 1e6, mn: 1e6, million: 1e6, b: 1e9 }[m[2]] || 1;
  return Math.round(parseFloat(m[1]) * mult);
}
function inRange(n, v) {
  if (!v) return true;
  const mn = parseAmount(v.min), mx = parseAmount(v.max);
  if (mn === null && mx === null) return true;
  if (n === null || n === undefined || n === "" || isNaN(Number(n))) return false;
  const x = Number(n);
  return (mn === null || x >= mn) && (mx === null || x <= mx);
}
const shortNum = (n) => (n >= 1e6 ? `${+(n / 1e6).toFixed(2)}m` : n >= 1e3 ? `${+(n / 1e3).toFixed(1)}k` : String(n));
function filterIsSet(def, v) {
  if (def.type === "date") return !!(v && v.p);
  if (def.type === "range") return !!(v && (String(v.min || "").trim() || String(v.max || "").trim()));
  if (def.type === "toggle") return !!v;
  return v !== undefined && v !== null && v !== "";
}
function filterChipText(def, v) {
  if (def.type === "date") return `${def.label}: ${v.p === "custom" ? `${v.from || "…"} → ${v.to || "…"}` : DATE_PRESET_LABEL[v.p]}`;
  if (def.type === "range") {
    const mn = parseAmount(v.min), mx = parseAmount(v.max);
    return `${def.label}: ${mn !== null && mx !== null ? `${shortNum(mn)}–${shortNum(mx)}` : mn !== null ? `≥ ${shortNum(mn)}` : `≤ ${shortNum(mx)}`}`;
  }
  if (def.type === "toggle") return def.label;
  return `${def.label}: ${(def.options || []).find((o) => String(o.id) === String(v))?.label || v}`;
}
// Filters remembered per screen on this device
function useFilters(key, initial) {
  const storeKey = `origin_filters:${key}`;
  const [values, setValues] = useState(() => {
    try { const s = localStorage.getItem(storeKey); return s ? { ...initial, ...JSON.parse(s) } : initial; } catch (e) { return initial; }
  });
  useEffect(() => { try { localStorage.setItem(storeKey, JSON.stringify(values)); } catch (e) {} }, [storeKey, values]);
  const set = (k, v) => setValues((x) => ({ ...x, [k]: v }));
  const reset = () => setValues(initial);
  return [values, set, reset, setValues];
}

const fbCtl = { ...inputStyle, padding: "8px 10px", fontSize: 13, minHeight: 38 };
const pluralLabel = (l) => { const w = l.toLowerCase(); return /s$/.test(w) ? w : /[^aeiou]y$/.test(w) ? w.slice(0, -1) + "ies" : w + "s"; };
function FilterControl({ def, value, onChange }) {
  if (def.type === "select") {
    return (
      <Sel aria-label={def.label} value={value ?? ""} onChange={(e) => onChange(e.target.value)} style={{ ...fbCtl, appearance: "none", background: filterIsSet(def, value) ? "#FBF6EC" : "#fff", borderColor: filterIsSet(def, value) ? COLORS.gold : COLORS.border }}>
        <option value="">{def.all || `All ${pluralLabel(def.label)}`}</option>
        {(def.options || []).map((o) => <option key={o.id} value={o.id}>{o.label}</option>)}
      </Sel>
    );
  }
  if (def.type === "date") {
    const v = value || {};
    return (
      <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
        <Sel aria-label={def.label} value={v.p || ""} onChange={(e) => onChange({ ...v, p: e.target.value })} style={{ ...fbCtl, appearance: "none", flex: "1 1 140px", background: v.p ? "#FBF6EC" : "#fff", borderColor: v.p ? COLORS.gold : COLORS.border }}>
          {DATE_PRESETS.map(([id, label]) => <option key={id || "any"} value={id}>{id ? label : `${def.label}: any time`}</option>)}
        </Sel>
        {v.p === "custom" && (
          <>
            <input type="date" aria-label={`${def.label} from`} value={v.from || ""} onChange={(e) => onChange({ ...v, from: e.target.value })} style={{ ...fbCtl, flex: "1 1 130px" }} />
            <input type="date" aria-label={`${def.label} to`} value={v.to || ""} onChange={(e) => onChange({ ...v, to: e.target.value })} style={{ ...fbCtl, flex: "1 1 130px" }} />
          </>
        )}
      </div>
    );
  }
  if (def.type === "range") {
    const v = value || {};
    return (
      <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
        <input inputMode="decimal" aria-label={`${def.label} min`} placeholder={def.money ? "Min (e.g. 3m)" : "Min"} value={v.min || ""} onChange={(e) => onChange({ ...v, min: e.target.value })} style={{ ...fbCtl, minWidth: 0, flex: 1 }} />
        <span style={{ color: COLORS.textMuted }}>–</span>
        <input inputMode="decimal" aria-label={`${def.label} max`} placeholder={def.money ? "Max (e.g. 8m)" : "Max"} value={v.max || ""} onChange={(e) => onChange({ ...v, max: e.target.value })} style={{ ...fbCtl, minWidth: 0, flex: 1 }} />
      </div>
    );
  }
  if (def.type === "toggle") {
    return (
      <button type="button" onClick={() => onChange(!value)} className="chip" style={{ ...fbCtl, width: "100%", cursor: "pointer", fontWeight: 700, textAlign: "left", background: value ? COLORS.navy : "#fff", color: value ? "#fff" : COLORS.text, borderColor: value ? COLORS.navy : COLORS.border }}>
        {value ? "✓ " : ""}{def.label}
      </button>
    );
  }
  return null;
}

// defs: [{ id, label, type: "select"|"date"|"range"|"toggle", options, primary, money, all }]
function FilterBar({ id, defs, values, set, reset, setAll, count, noun = "results", searchPlaceholder, right }) {
  const [open, setOpen] = useState(false);
  const [naming, setNaming] = useState(null);
  const viewsKey = `origin_views:${id}`;
  const [views, setViews] = useState(() => { try { return JSON.parse(localStorage.getItem(viewsKey) || "[]"); } catch (e) { return []; } });
  const saveViews = (v) => { setViews(v); try { localStorage.setItem(viewsKey, JSON.stringify(v)); } catch (e) {} };
  const shown = defs.filter((d) => !d.hidden && (d.type !== "select" || (d.options || []).length > 0));
  const primary = shown.filter((d) => d.primary);
  const more = shown.filter((d) => !d.primary);
  const active = shown.filter((d) => filterIsSet(d, values[d.id]));
  const activeMore = more.filter((d) => filterIsSet(d, values[d.id])).length;
  const clearOne = (d) => set(d.id, d.type === "date" ? { p: "" } : d.type === "range" ? { min: "", max: "" } : d.type === "toggle" ? false : "");
  return (
    <div className="filterbar" style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 12 }}>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
        {searchPlaceholder !== undefined && (
          <div style={{ position: "relative", flex: "2 1 220px" }}>
            <Search size={15} style={{ position: "absolute", left: 11, top: 12, color: COLORS.textMuted }} />
            <input aria-label="Search" style={{ ...fbCtl, width: "100%", paddingLeft: 32 }} value={values.q || ""} onChange={(e) => set("q", e.target.value)} placeholder={searchPlaceholder} />
          </div>
        )}
        {primary.map((d) => <div key={d.id} style={{ flex: d.type === "date" ? "1 1 170px" : d.type === "range" ? "1 1 200px" : "1 1 140px", minWidth: 0 }}><FilterControl def={d} value={values[d.id]} onChange={(v) => set(d.id, v)} /></div>)}
        {more.length > 0 && (
          <button type="button" onClick={() => setOpen((o) => !o)} className="chip" style={{ ...fbCtl, width: "auto", flex: "0 0 auto", cursor: "pointer", fontWeight: 700, display: "flex", alignItems: "center", gap: 6, background: open || activeMore ? COLORS.navy : "#fff", color: open || activeMore ? "#fff" : COLORS.navy, borderColor: COLORS.navy }}>
            <Layers size={14} /> Filters{activeMore ? ` · ${activeMore}` : ""}
          </button>
        )}
        {right}
      </div>
      {open && more.length > 0 && (() => {
        const panel = (
        <div className="glass fade-in card fb-more" style={{ border: `1px solid ${COLORS.border}`, padding: 12, display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(210px, 1fr))", gap: 10 }}>
          <div className="fb-done" style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}><b style={{ color: COLORS.navy }}>Filters</b><button type="button" onClick={() => setOpen(false)} style={{ ...btnPrimary, padding: "6px 16px" }}>Done</button></div>
          {more.map((d) => (
            <div key={d.id} style={{ display: "flex", flexDirection: "column", gap: 4 }}>
              {d.type !== "toggle" && <span style={{ fontSize: 11, fontWeight: 800, color: COLORS.textMuted, letterSpacing: 0.3 }}>{d.label.toUpperCase()}</span>}
              <FilterControl def={d} value={values[d.id]} onChange={(v) => set(d.id, v)} />
            </div>
          ))}
        </div>
        );
        const phone = typeof window !== "undefined" && window.matchMedia && window.matchMedia("(max-width: 760px)").matches;
        return phone ? createPortal(<><div className="fb-backdrop" onClick={() => setOpen(false)} />{panel}</>, document.body) : panel;
      })()}
      <div style={{ display: "flex", gap: 6, flexWrap: "wrap", alignItems: "center", fontSize: 12.5 }}>
        <span style={{ color: COLORS.textMuted, fontWeight: 600, marginRight: 4 }}>{count} {noun}</span>
        {active.map((d) => (
          <button key={d.id} type="button" onClick={() => clearOne(d)} className="pill" style={{ border: "none", background: "#FBF1E6", color: COLORS.navy, borderRadius: 999, padding: "4px 10px", fontSize: 12, fontWeight: 600, cursor: "pointer" }}>
            {filterChipText(d, values[d.id])} ×
          </button>
        ))}
        {(active.length > 0 || (values.q || "").trim()) && <button type="button" onClick={reset} style={{ border: "none", background: "none", color: COLORS.danger, fontWeight: 700, cursor: "pointer", fontSize: 12 }}>Clear all</button>}
        <span style={{ flex: 1 }} />
        {views.map((v, i) => (
          <span key={i} className="pill" style={{ display: "inline-flex", alignItems: "center", gap: 4, background: COLORS.creamDark, borderRadius: 999, padding: "3px 4px 3px 10px" }}>
            <button type="button" onClick={() => setAll(v.values)} style={{ border: "none", background: "none", cursor: "pointer", fontWeight: 700, color: COLORS.navy, fontSize: 12, padding: 0 }}>★ {v.name}</button>
            <button type="button" aria-label={`Remove ${v.name}`} onClick={() => saveViews(views.filter((_, j) => j !== i))} style={{ border: "none", background: "none", cursor: "pointer", color: COLORS.textMuted, fontSize: 12 }}>×</button>
          </span>
        ))}
        {naming === null ? (
          (active.length > 0 || (values.q || "").trim()) && <button type="button" onClick={() => setNaming("")} style={{ border: "none", background: "none", color: COLORS.navy, fontWeight: 700, cursor: "pointer", fontSize: 12 }}>☆ Save this view</button>
        ) : (
          <span style={{ display: "inline-flex", gap: 4 }}>
            <input autoFocus aria-label="View name" value={naming} onChange={(e) => setNaming(e.target.value)} placeholder="Name, e.g. My overdue" style={{ ...fbCtl, minHeight: 30, padding: "4px 8px", width: 170 }}
              onKeyDown={(e) => { if (e.key === "Enter" && naming.trim()) { saveViews([...views, { name: naming.trim(), values }]); setNaming(null); } if (e.key === "Escape") setNaming(null); }} />
            <button type="button" onClick={() => { if (naming.trim()) { saveViews([...views, { name: naming.trim(), values }]); setNaming(null); } }} style={{ border: "none", background: COLORS.navy, color: "#fff", borderRadius: 999, padding: "0 12px", fontWeight: 700, cursor: "pointer", fontSize: 12 }}>Save</button>
          </span>
        )}
      </div>
    </div>
  );
}
const opt = (list, idKey = "id", labelKey = "label") => list.map((x) => (typeof x === "string" ? { id: x, label: x } : { id: x[idKey], label: x[labelKey] }));

const CLIENT_FILTERS_INITIAL = { q: "", stage: "", assignedTo: "", source: "", interest: "", projectId: "", budget: { min: "", max: "" }, added: { p: "" }, lastUpdate: { p: "" }, quiet: "", nextAt: { p: "" }, meeting: { p: "" }, overdue: false, needsFollowUp: false, sent: "", closedReason: "" };
function ClientsList({ clients, users, projects, units, clientUnitLinks, clientProjectLinks = [], activity, visibleSalesIds, currentUserId, isManager, onOpenClient, onOpenUnit, onContact }) {
  const [view, setView] = useState("active"); // "active" | "closed"
  const [fv, setF, resetF, setAllF] = useFilters("clients", CLIENT_FILTERS_INITIAL);
  const [needs, setNeeds] = useState(() => { try { const f = sessionStorage.getItem("origin_clients_needs"); if (f !== null) { sessionStorage.removeItem("origin_clients_needs"); return f === "1"; } } catch (e) {} return !isManager; }); // "Needs you" picked (sales start there)

  const visible = clients.filter((c) => visibleSalesIds.includes(c.assignedTo));
  // Not-qualified / closed clients are hidden from the normal list — sales don't see them at all,
  // managers/admin/CEO see them only in their own separate views below.
  const activeVisible = visible.filter((c) => c.stage !== "not_qualified" && c.stage !== "closed");
  const closedVisible = visible.filter((c) => c.stage === "closed" || c.stage === "not_qualified");
  const base = !isManager ? activeVisible : view === "closed" ? closedVisible : activeVisible;

  const sentIds = useMemo(() => new Set(activity.filter((a) => a.action === "unit_sent").map((a) => a.clientId)), [activity]);
  const endToday = new Date(); endToday.setHours(23, 59, 59, 999);
  const needsYou = (c) => (c.nextActionAt && !c.nextActionDone && new Date(c.nextActionAt) <= endToday) || (c.meetingAt && isToday(c.meetingAt)) || clientNotifications(c, activity).length > 0;
  const matches = (c, skip) => {
    if (skip !== "stage" && fv.stage && c.stage !== fv.stage) return false;
    if (skip !== "person" && fv.assignedTo && c.assignedTo !== fv.assignedTo) return false;
    if (skip !== "needs" && needs && !needsYou(c)) return false;
    if (fv.source && c.source !== fv.source) return false;
    if (fv.interest && (c.interest || "buy") !== fv.interest) return false;
    if (fv.projectId && !clientProjectLinks.some((l) => l.client_id === c.id && l.project_id === fv.projectId)) return false;
    if (!inRange(c.budget, fv.budget)) return false;
    if (!inDate(c.createdAt, fv.added)) return false;
    const last = clientLastActivityAt(c, activity);
    if (!inDate(last, fv.lastUpdate)) return false;
    if (fv.quiet && Date.now() - new Date(last).getTime() < Number(fv.quiet) * MS_DAY) return false;
    if (!inDate(c.nextActionDone ? null : c.nextActionAt, fv.nextAt)) return false;
    if (!inDate(c.meetingAt, fv.meeting)) return false;
    if (fv.overdue && !(c.nextActionAt && !c.nextActionDone && new Date(c.nextActionAt) < new Date())) return false;
    if (fv.needsFollowUp && clientNotifications(c, activity).length === 0) return false;
    if (fv.sent === "yes" && !sentIds.has(c.id)) return false;
    if (fv.sent === "no" && sentIds.has(c.id)) return false;
    if (fv.closedReason && c.closedReason !== fv.closedReason) return false;
    if ((fv.q || "").trim()) {
      const q = fv.q.trim().toLowerCase(), d = q.replace(/\D/g, "");
      if (!(c.name.toLowerCase().includes(q) || (d.length >= 3 && String(c.phone).replace(/\D/g, "").includes(d)) || (c.notes || "").toLowerCase().includes(q))) return false;
    }
    return true;
  };
  const filtered = base.filter((c) => matches(c)).sort((a, b) => new Date(clientLastActivityAt(b, activity)) - new Date(clientLastActivityAt(a, activity)));
  // counts on the chips: each chip counts with every other choice applied except its own
  const stageCounts = {}; base.filter((c) => matches(c, "stage")).forEach((c) => { stageCounts[c.stage] = (stageCounts[c.stage] || 0) + 1; });
  const personCounts = {}; base.filter((c) => matches(c, "person")).forEach((c) => { personCounts[c.assignedTo] = (personCounts[c.assignedTo] || 0) + 1; });
  const needsCount = base.filter((c) => matches(c, "needs") && needsYou(c)).length;
  const otherSet = Object.entries(fv).some(([k, v]) => !["stage", "assignedTo"].includes(k) && JSON.stringify(v) !== JSON.stringify(CLIENT_FILTERS_INITIAL[k]));
  const picked = !!(fv.stage || fv.assignedTo || needs || otherSet || view === "closed");

  const assignableUsers = users.filter((u) => visibleSalesIds.includes(u.id));
  const selectableStages = view === "active" ? PIPELINE_STAGES.concat(EXCEPTION_STAGES) : [];

  // Group rows by the assigned sales person, like a spreadsheet with one section per person.
  const groups = {};
  filtered.forEach((c) => {
    const key = c.assignedTo || "unassigned";
    if (!groups[key]) groups[key] = [];
    groups[key].push(c);
  });
  const groupOrder = Object.keys(groups).sort((a, b) => {
    const an = users.find((u) => u.id === a)?.name || "";
    const bn = users.find((u) => u.id === b)?.name || "";
    return an.localeCompare(bn);
  });

  const lastActionLabel = (client) => {
    const rows = activity.filter((a) => a.clientId === client.id).sort((a, b) => new Date(b.changedAt) - new Date(a.changedAt));
    const row = rows[0];
    if (!row) return "";
    if (row.action === "stage_change") return `${STAGE_LABEL[row.oldValue] || row.oldValue} \u2192 ${STAGE_LABEL[row.newValue] || row.newValue}`;
    if (row.action === "created") return "Client created";
    if (row.action === "closed") return "Lead removed";
    if (row.note) return row.note;
    return "";
  };

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
      {isManager && (
        <div style={{ display: "flex", gap: 6 }}>
          <button onClick={() => setView("active")} style={{ border: "none", borderRadius: 20, padding: "6px 14px", fontSize: 12.5, fontWeight: 600, cursor: "pointer", background: view === "active" ? COLORS.navy : COLORS.creamDark, color: view === "active" ? "#fff" : COLORS.text }}>Active ({activeVisible.length})</button>
          <button onClick={() => setView("closed")} style={{ border: "none", borderRadius: 20, padding: "6px 14px", fontSize: 12.5, fontWeight: 600, cursor: "pointer", background: view === "closed" ? COLORS.textMuted : COLORS.creamDark, color: view === "closed" ? "#fff" : COLORS.text }}>Closed ({closedVisible.length})</button>
        </div>
      )}

      {view === "active" && (
        <div data-client-counts style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 2 }}>
          <div className="chip-row">
            <button type="button" data-needs className={`count-chip${needs ? " on" : ""}`} style={needs ? undefined : { borderColor: COLORS.danger, color: COLORS.danger }} onClick={() => setNeeds((x) => !x)}>Needs you <b>{needsCount}</b></button>
            {PIPELINE_STAGES.concat(EXCEPTION_STAGES).filter((st) => st.id !== "deal_done").map((st) => (
              <button type="button" key={st.id} data-stage-chip={st.id} className={`count-chip${fv.stage === st.id ? " on" : ""}${stageCounts[st.id] ? "" : " zero"}`} onClick={() => setF("stage", fv.stage === st.id ? "" : st.id)}>{st.label} <b>{stageCounts[st.id] || 0}</b></button>
            ))}
          </div>
          {isManager && assignableUsers.length > 1 && (
            <div className="chip-row">
              {assignableUsers.filter((u) => personCounts[u.id] || fv.assignedTo === u.id).sort((a, b) => (personCounts[b.id] || 0) - (personCounts[a.id] || 0)).map((u) => (
                <button type="button" key={u.id} data-person-chip={u.id} className={`count-chip${fv.assignedTo === u.id ? " on" : ""}`} onClick={() => setF("assignedTo", fv.assignedTo === u.id ? "" : u.id)}>{u.name.split(" ")[0]} <b>{personCounts[u.id] || 0}</b></button>
              ))}
            </div>
          )}
        </div>
      )}

      <FilterBar id="clients" values={fv} set={setF} reset={resetF} setAll={setAllF} count={filtered.length} noun={filtered.length === 1 ? "client" : "clients"}
        searchPlaceholder="Search name, phone or notes…"
        defs={[
          { id: "stage", label: "Stage", type: "select", options: selectableStages.map((st) => ({ id: st.id, label: st.label })), hidden: view !== "active" },
          { id: "assignedTo", label: "Sales", type: "select", all: "All sales", options: assignableUsers.length > 1 ? opt(assignableUsers, "id", "name") : [] },
          { id: "lastUpdate", label: "Last update", type: "date" },
          { id: "interest", label: "Looking to", type: "select", all: "Buy and rent", options: [{ id: "buy", label: "Buy" }, { id: "rent", label: "Rent" }] },
          { id: "source", label: "Source", type: "select", options: SOURCES.map((x) => ({ id: x.id, label: x.label })) },
          { id: "projectId", label: "Wanted project", type: "select", options: opt(projects.filter((pr) => clientProjectLinks.some((l) => l.project_id === pr.id)), "id", "name") },
          { id: "budget", label: "Budget", type: "range", money: true },
          { id: "added", label: "Added", type: "date" },
          { id: "nextAt", label: "Next follow-up", type: "date" },
          { id: "meeting", label: "Meeting date", type: "date" },
          { id: "quiet", label: "No update for", type: "select", all: "No update for: any", options: [{ id: "3", label: "3+ days" }, { id: "7", label: "7+ days" }, { id: "14", label: "14+ days" }, { id: "30", label: "30+ days" }] },
          { id: "sent", label: "Units sent", type: "select", all: "Units sent: any", options: [{ id: "yes", label: "Sent units" }, { id: "no", label: "No units sent yet" }] },
          { id: "closedReason", label: "Closed reason", type: "select", options: CLOSE_REASONS.map((r) => ({ id: r.id, label: r.label })), hidden: view !== "closed" },
          { id: "overdue", label: "Follow-up overdue", type: "toggle", hidden: view !== "active" },
          { id: "needsFollowUp", label: "Needs attention", type: "toggle", hidden: view !== "active" },
        ]}
      />

      {!picked ? (
        <div data-pick-hint style={{ fontSize: 13, color: COLORS.textMuted, background: "#fff", border: `1px solid ${COLORS.border}`, borderRadius: 14, padding: 20, textAlign: "center" }}>Tap a number above to see those clients.</div>
      ) : filtered.length === 0 ? (
        <div style={{ fontSize: 13, color: COLORS.textMuted, background: "#fff", border: `1px solid ${COLORS.border}`, borderRadius: 14, padding: 20, textAlign: "center" }}>No clients here.</div>
      ) : (
        <div data-client-list className="card" style={{ padding: 0, overflow: "hidden" }}>
          {filtered.slice(0, 300).map((c) => {
            const person = users.find((u) => u.id === c.assignedTo);
            const due = c.nextActionAt && !c.nextActionDone ? new Date(c.nextActionAt) : null;
            const overdue = due && due < new Date();
            const need = [c.interest === "rent" ? "Rent" : null, c.budget ? egp(c.budget) : null, (c.notes || "").split("\n")[0].slice(0, 60) || null].filter(Boolean).join(" · ");
            return (
              <div key={c.id} data-client-row onClick={() => onOpenClient(c)} className="hover-row" style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 12px", borderBottom: `1px solid ${COLORS.border}`, cursor: "pointer" }}>
                <div style={{ width: 32, height: 32, borderRadius: "50%", background: COLORS.navy, color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 11, fontWeight: 700, flexShrink: 0 }}>{initials(c.name)}</div>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ display: "flex", gap: 6, alignItems: "center", flexWrap: "wrap" }}>
                    <span style={{ fontWeight: 700, fontSize: 13.5, color: COLORS.navy }}>{c.name}</span>
                    <ClientStageBadge stage={c.stage} />
                    {isManager && !fv.assignedTo && person && <span style={{ fontSize: 11.5, color: COLORS.textMuted }}>· {person.name.split(" ")[0]}</span>}
                  </div>
                  <div style={{ fontSize: 12, color: COLORS.textMuted, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                    {due ? <span style={{ color: overdue ? COLORS.danger : COLORS.navy, fontWeight: 700 }}>{overdue ? "Overdue" : "Next"} · {formatDateTime(c.nextActionAt)}{need ? " · " : ""}</span> : null}{need || timeAgo(clientLastActivityAt(c, activity))}
                  </div>
                </div>
                <ContactButtons phone={c.phone} size={15} onContact={onContact ? (k) => onContact(c, k) : undefined} />
              </div>
            );
          })}
          {filtered.length > 300 && <div style={{ padding: 10, fontSize: 12, color: COLORS.textMuted, textAlign: "center" }}>Showing 300 of {filtered.length} — narrow it down with a stage or a filter.</div>}
        </div>
      )}
    </div>
  );
}

// ---------- CEO/Admin Dashboard + Reports ----------
function isToday(iso) {
  if (!iso) return false;
  const d = new Date(iso);
  const now = new Date();
  return d.getFullYear() === now.getFullYear() && d.getMonth() === now.getMonth() && d.getDate() === now.getDate();
}
const REPORT_STALE_DAYS = 3;

// yyyy-mm-dd in the browser's local time, for comparing against <input type="date"> values.
function dateKey(iso) {
  const d = new Date(iso);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}
function todayKey() { return dateKey(new Date().toISOString()); }
function daysAgoKey(n) {
  const d = new Date();
  d.setDate(d.getDate() - n);
  return dateKey(d.toISOString());
}

// A filterable attendance log (date range + optional person), shared by the Dashboard (all
// people) and the Reports profile (one person).
function AttendanceLog({ attendance, users, defaultDays = 7, showPerson = true }) {
  const [from, setFrom] = useState(daysAgoKey(defaultDays));
  const [to, setTo] = useState(todayKey());

  const rows = attendance
    .filter((a) => { const k = dateKey(a.checkedInAt); return k >= from && k <= to; })
    .sort((a, b) => new Date(b.checkedInAt) - new Date(a.checkedInAt));

  return (
    <div style={{ background: "#fff", border: `1px solid ${COLORS.border}`, borderRadius: 14, padding: 14, marginTop: 10 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10, flexWrap: "wrap", gap: 8 }}>
        <div style={{ fontWeight: 700, fontSize: 13.5, color: COLORS.navy }}>Attendance ({rows.length})</div>
        <div style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 12.5, color: COLORS.textMuted }}>
          From <input type="date" value={from} onChange={(e) => setFrom(e.target.value)} style={{ ...inputStyle, width: "auto", padding: "5px 8px" }} />
          To <input type="date" value={to} onChange={(e) => setTo(e.target.value)} style={{ ...inputStyle, width: "auto", padding: "5px 8px" }} />
        </div>
      </div>
      {rows.length === 0 ? (
        <div style={{ color: COLORS.textMuted, fontSize: 12.5 }}>No check-ins in this range.</div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
          {rows.map((a) => {
            const u = users.find((usr) => usr.id === a.userId);
            return (
              <div key={a.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10, padding: "7px 10px", border: `1px solid ${COLORS.border}`, borderRadius: 10 }}>
                {showPerson && <div style={{ fontWeight: 600, fontSize: 12.5, color: COLORS.text }}>{u?.name || "—"}</div>}
                <div style={{ fontSize: 11.5, color: COLORS.textMuted }}>{formatDateTime(a.checkedInAt)}</div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

// A feedback on a client (not the automatic lines) — same rule as the ranking (is_client_feedback in SQL)
// Don't-call-again info for a lead (its main number or any other number), or null
const coldDncFor = (lead, dncMap) => {
  if (!lead || !dncMap) return null;
  for (const p of [lead.phone, ...(Array.isArray(lead.other_phones) ? lead.other_phones : [])]) { const d = dncMap[phoneKey(p)]; if (d) return d; }
  return null;
};
const cairoDay = (iso) => { try { return new Date(iso).toLocaleDateString("en-CA", { timeZone: "Africa/Cairo" }); } catch (e) { return String(iso).slice(0, 10); } };
const isClientFeedback = (a) => ["quick_reply", "stage_change", "note", "voice", "closed", "outcome"].includes(a.action)
  && !/^(Sent a unit|Lead came in again|Changed by Admin)/.test(a.note || "");
// ---------- Daily report: one row per person, like a spreadsheet ----------
const DAILY_COLS = [
  ["checkin", "Check-in"], ["cold", "Cold calls"], ["clientCalls", "Client calls"], ["seller", "Seller updates"], ["total", "Total calls"], ["tries", "Tries"],
  ["wa", "WhatsApp"], ["mBooked", "Meetings booked"], ["mDone", "Meetings done"], ["newClients", "New clients"], ["newUnits", "New units"], ["selling", "Selling (cold)"],
  ["resv", "Reservations"], ["deals", "Deals done"],
];
function DailyReport({ profile, users, visibleSalesIds, clients, activity, units, attendance, settings, fin, getToken, onOpenClient, onOpenUnit }) {
  const [fv, setF, resetF, setAllF] = useFilters("daily-report", { when: { p: "today" }, person: "" });
  const range = dateRangeOf(fv.when) || [new Date(2024, 0, 1), new Date(Date.now() + MS_DAY)];
  const [extra, setExtra] = useState({ cold: [], unitAct: [], leads: {}, key: "", loading: true, err: "" });
  const [sort, setSort] = useState({ k: "", dir: -1 });
  const [drill, setDrill] = useState(null);
  const rkey = `${range[0].toISOString()}|${range[1].toISOString()}`;
  useEffect(() => {
    let off = false;
    (async () => {
      setExtra((x) => ({ ...x, loading: true, err: "" }));
      try {
        const t = await getToken();
        const q = `&created_at=gte.${range[0].toISOString()}&created_at=lt.${range[1].toISOString()}&order=created_at.desc`;
        const [cold, unitAct] = await Promise.all([
          db.selectAll("cold_activity", q, t).catch(() => []),
          db.selectAll("unit_activity", q, t).catch(() => []),
        ]);
        const ids = [...new Set(cold.map((a) => a.lead_id).filter(Boolean))]; // numbers from deleted sheets have no id
        const leads = {};
        for (let k = 0; k < ids.length; k += 150) {
          const rows = await db.select("cold_leads", `&id=in.(${ids.slice(k, k + 150).join(",")})&select=id,owner_name,phone,project_name`, t).catch(() => []);
          (rows || []).forEach((r) => { leads[r.id] = r; });
        }
        if (!off) setExtra({ cold, unitAct, leads, key: rkey, loading: false, err: "" });
      } catch (e) { if (!off) setExtra((x) => ({ ...x, loading: false, err: e.message || "Couldn't load" })); }
    })();
    return () => { off = true; };
  }, [rkey]); // eslint-disable-line
  const inR = (iso) => { if (!iso) return false; const d = new Date(iso); return d >= range[0] && d < range[1]; };
  const people = users.filter((u) => !["pending", "admin", "ceo"].includes(u.role) && (isFinanceAdmin(profile) || visibleSalesIds.includes(u.id)) && (!fv.person || u.id === fv.person));
  const oneDay = range[1] - range[0] <= MS_DAY + 3600000;
  const cut = lateCutoff(settings);
  const clientName = (id) => (clients.find((c) => c.id === id) || {}).name || "Client";
  const unitName = (id) => { const u = units.find((x) => x.id === id); return u ? `${u.type || "Unit"} ${u.unitNumber || ""}` : "Unit"; };
  const leadName = (id) => { const l = extra.leads[id]; return l ? `${l.owner_name || "Owner"} · ${l.phone}${l.project_name ? ` · ${l.project_name}` : ""}` : "Cold number"; };
  const isMeetingDone = (a) => (a.action === "quick_reply" && a.fieldName === "meeting_done") || (a.action === "stage_change" && (a.newValue === "meeting_done" || (a.oldValue === "meeting_generated" && a.newValue !== "meeting_generated" && a.newValue !== "lost")));
  const sidesOfAgent = (d, uid) => { const x = [...new Set((fin.dealAgents || []).filter((a) => a.deal_id === d.id && a.agent_id === uid).map((a) => a.side))]; return x.length ? x : ["buyer"]; }; // both sides = 2 deals
  const dealsOf = (uid, field) => (fin?.deals || []).filter((d) => inR(d[field]) && d.status !== "cancelled" && (fin.dealAgents || []).some((a) => a.deal_id === d.id && a.agent_id === uid));
  const rows = people.map((u) => {
    const act = activity.filter((a) => a.changedBy === u.id && inR(a.changedAt));
    const cold = extra.cold.filter((a) => a.user_id === u.id);
    const st = attendanceStats(attendance, u.id, range, settings);
    const firstIn = st.days.find((x) => x.inAt);
    const items = {
      // each number counts once a day (its latest feedback), like the ranking
      cold: Object.values(cold.filter((a) => a.action === "outcome").reduce((m, a) => {
        const k = `${a.phone || a.lead_id || a.id}:${cairoDay(a.created_at)}`; const x = m[k];
        if (!x) m[k] = { a, n: 1 }; else { x.n++; if (a.created_at > x.a.created_at) x.a = a; }
        return m;
      }, {})).map(({ a, n }) => ({ at: a.created_at, label: `${a.lead_id ? leadName(a.lead_id) : a.phone ? `${a.phone} (deleted sheet)` : "Number from a deleted sheet"} — ${COLD_STATUS_LABEL[a.value] || a.value}${n > 1 ? ` (${n} feedbacks)` : ""}` })),
      clientCalls: act.filter((a) => isClientFeedback(a)).map((a) => ({ at: a.changedAt, label: `${clientName(a.clientId)} — ${a.action === "stage_change" ? `stage → ${STAGE_LABEL[a.newValue] || a.newValue}` : a.action === "quick_reply" ? (a.fieldName || "update").replace(/_/g, " ") : a.action === "voice" ? "voice note" : a.action}`, client: a.clientId })),
      seller: extra.unitAct.filter((a) => a.user_id === u.id && (a.action === "updated" || a.action === "checked")).map((a) => ({ at: a.created_at, label: `${a.unit_id ? unitName(a.unit_id) : "Deleted unit"} — ${a.action === "checked" ? "still available" : Array.isArray(a.fields) && a.fields.length ? a.fields.slice(0, 4).join(", ").replace(/_/g, " ") : "updated"}`, unit: a.unit_id })),
      tries: [...act.filter((a) => a.action === "call").map((a) => ({ at: a.changedAt, label: `${clientName(a.clientId)} (client)`, client: a.clientId })),
        ...Object.values(cold.filter((a) => a.action === "call").reduce((m, a) => { const k = `${a.lead_id || a.id}:${Math.floor(new Date(a.created_at) / 120000)}`; if (!m[k]) m[k] = { at: a.created_at, label: a.lead_id ? leadName(a.lead_id) : "Number from a deleted sheet" }; return m; }, {}))],
      wa: [...act.filter((a) => a.action === "whatsapp").map((a) => ({ at: a.changedAt, label: clientName(a.clientId), client: a.clientId })), ...cold.filter((a) => a.action === "whatsapp").map((a) => ({ at: a.created_at, label: `${leadName(a.lead_id)} (cold)` }))],
      mBooked: act.filter((a) => a.action === "stage_change" && a.newValue === "meeting_generated").map((a) => ({ at: a.changedAt, label: clientName(a.clientId), client: a.clientId })),
      mDone: act.filter(isMeetingDone).map((a) => ({ at: a.changedAt, label: clientName(a.clientId), client: a.clientId })),
      newClients: clients.filter((c) => (c.createdBy || c.assignedTo) === u.id && inR(c.createdAt)).map((c) => ({ at: c.createdAt, label: c.name, client: c.id })),
      newUnits: units.filter((x) => (x.createdBy ? x.createdBy === u.id : x.salesIds.includes(u.id)) && inR(x.createdAt)).map((x) => ({ at: x.createdAt, label: unitName(x.id), unit: x.id })),
      selling: cold.filter((a) => a.action === "outcome" && a.value === "selling").map((a) => ({ at: a.created_at, label: leadName(a.lead_id) })),
      resv: dealsOf(u.id, "reserved_at").flatMap((d) => sidesOfAgent(d, u.id).map((sd) => ({ at: d.reserved_at, label: `${d.unit_label || d.client_label || "Deal"}${d.sides === "both" ? ` (${sd})` : ""}` }))),
      deals: dealsOf(u.id, "done_at").flatMap((d) => sidesOfAgent(d, u.id).map((sd) => ({ at: d.done_at, label: `${d.unit_label || d.client_label || "Deal"}${d.sides === "both" ? ` (${sd})` : ""}` }))),
    };
    items.total = [...items.cold, ...items.clientCalls, ...items.seller];
    const checkin = oneDay ? (firstIn ? new Date(firstIn.inAt).toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" }) : "—") : `${st.present} days${st.late ? ` · ${st.late} late` : ""}`;
    return { u, items, checkin, late: oneDay ? !!(firstIn && firstIn.late) : st.late > 0, checkinSort: oneDay ? (firstIn ? new Date(firstIn.inAt).getTime() : Infinity) : -st.present };
  });
  const val = (r, k) => (k === "checkin" ? r.checkinSort : r.items[k].length);
  const cmp = (x, y) => (x === y ? 0 : x > y ? 1 : -1);
  const sorted = sort.k ? [...rows].sort((a, b) => cmp(val(b, sort.k), val(a, sort.k)) * (sort.dir < 0 ? 1 : -1) || a.u.name.localeCompare(b.u.name)) : [...rows].sort((a, b) => a.u.name.localeCompare(b.u.name));
  const total = (k) => rows.reduce((s, r) => s + r.items[k].length, 0);
  const label = fv.when?.p === "custom" ? `${fv.when.from || "…"} → ${fv.when.to || "…"}` : DATE_PRESET_LABEL[fv.when?.p] || "Any time";
  const download = () => {
    const headers = ["Name", "Role", ...DAILY_COLS.map(([, l]) => l)];
    const data = sorted.map((r) => [r.u.name, ROLE_LABEL[r.u.role] || r.u.role, r.checkin, ...DAILY_COLS.slice(1).map(([k]) => r.items[k].length)]);
    data.push(["Total", "", "", ...DAILY_COLS.slice(1).map(([k]) => total(k))]);
    saveBlob(makeXlsx(headers, data, "Report"), `Daily-report_${label.replace(/[^\w-]+/g, "-")}_${todayKey()}.xlsx`);
  };
  const th = { padding: "8px 10px", fontSize: 12, fontWeight: 700, color: COLORS.navy, whiteSpace: "nowrap", cursor: "pointer", textAlign: "center", borderBottom: `1.5px solid ${COLORS.navy}`, position: "sticky", top: 0, background: "#fff" };
  const td = { padding: "7px 10px", fontSize: 13, textAlign: "center", borderBottom: `1px solid ${COLORS.border}`, whiteSpace: "nowrap" };
  const peopleOpts = users.filter((u) => !["pending", "admin", "ceo"].includes(u.role) && (isFinanceAdmin(profile) || visibleSalesIds.includes(u.id)));
  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8, flexWrap: "wrap", marginBottom: 10 }}>
        <div style={{ fontWeight: 700, fontSize: 16, color: COLORS.navy }}>Daily report <span style={{ fontWeight: 500, fontSize: 13, color: COLORS.textMuted }}>· {label}{extra.loading ? " · loading…" : ""}</span></div>
        <button onClick={download} style={{ ...btnGhost, padding: "6px 12px" }}>⬇ Download Excel</button>
      </div>
      <FilterBar id="daily-report" values={fv} set={setF} reset={resetF} setAll={setAllF} count={rows.length} noun={rows.length === 1 ? "person" : "people"}
        defs={[
          { id: "when", label: "Period", type: "date", primary: true },
          { id: "person", label: "Person", type: "select", primary: true, all: "Everyone", options: opt(peopleOpts, "id", "name") },
        ]} />
      {extra.err && <div style={{ color: COLORS.danger, fontSize: 12.5, marginBottom: 8 }}>Some numbers couldn't load ({extra.err}).</div>}
      <div className="card" style={{ background: "#fff", border: `1px solid ${COLORS.border}`, borderRadius: 14, overflow: "auto", maxHeight: "70vh" }}>
        <table style={{ borderCollapse: "collapse", width: "100%", minWidth: 1100 }}>
          <thead>
            <tr>
              <th style={{ ...th, textAlign: "left", position: "sticky", left: 0, zIndex: 2 }} onClick={() => setSort({ k: "", dir: -1 })}>Name</th>
              {DAILY_COLS.map(([k, l]) => (
                <th key={k} style={th} onClick={() => setSort((x) => ({ k, dir: x.k === k ? -x.dir : -1 }))}>{l}{sort.k === k ? (sort.dir < 0 ? " ↓" : " ↑") : ""}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {sorted.map((r) => (
              <tr key={r.u.id}>
                <td style={{ ...td, textAlign: "left", fontWeight: 700, color: COLORS.navy, position: "sticky", left: 0, background: "#fff" }}>{r.u.name}<div style={{ fontSize: 11, fontWeight: 400, color: COLORS.textMuted }}>{ROLE_LABEL[r.u.role]}</div></td>
                <td style={{ ...td, color: r.late ? COLORS.danger : r.checkin === "—" ? COLORS.textMuted : COLORS.success, fontWeight: 700 }} title={oneDay ? `Late after ${cut.label}` : ""}>{r.checkin}</td>
                {DAILY_COLS.slice(1).map(([k, l]) => {
                  const n = r.items[k].length;
                  return <td key={k} style={{ ...td, cursor: n ? "pointer" : "default", fontWeight: n ? 700 : 400, color: n ? COLORS.text : "#BBB" }} onClick={() => n && setDrill({ title: `${r.u.name} · ${l} · ${label}`, list: r.items[k] })}>{n}</td>;
                })}
              </tr>
            ))}
            {sorted.length > 1 && (
              <tr style={{ background: COLORS.cream }}>
                <td style={{ ...td, textAlign: "left", fontWeight: 800, position: "sticky", left: 0, background: COLORS.cream }}>Total</td>
                <td style={td}>—</td>
                {DAILY_COLS.slice(1).map(([k]) => <td key={k} style={{ ...td, fontWeight: 800 }}>{total(k)}</td>)}
              </tr>
            )}
            {sorted.length === 0 && <tr><td colSpan={DAILY_COLS.length + 1} style={{ ...td, color: COLORS.textMuted, padding: 20 }}>No one to show.</td></tr>}
          </tbody>
        </table>
      </div>
      <div style={{ fontSize: 11.5, color: COLORS.textMuted, marginTop: 6 }}>Tap a number to see the details. Tap a column title to sort.</div>
      {drill && (
        <FinModal title={drill.title} onClose={() => setDrill(null)} width={560}>
          <div style={{ display: "flex", flexDirection: "column", gap: 4, maxHeight: "60vh", overflowY: "auto" }}>
            {[...drill.list].sort((a, b) => new Date(b.at) - new Date(a.at)).map((x, i) => (
              <div key={i} onClick={() => { if (x.client && onOpenClient) { setDrill(null); onOpenClient(x.client); } else if (x.unit && onOpenUnit) { const u = units.find((y) => y.id === x.unit); if (u) { setDrill(null); onOpenUnit(u); } } }}
                style={{ display: "flex", justifyContent: "space-between", gap: 10, fontSize: 13, padding: "7px 8px", borderRadius: 10, background: i % 2 ? "#fff" : COLORS.cream, cursor: x.client || x.unit ? "pointer" : "default" }}>
                <span dir="auto">{x.label}</span>
                <span style={{ color: COLORS.textMuted, whiteSpace: "nowrap" }}>{formatDateTime(x.at)}</span>
              </div>
            ))}
          </div>
        </FinModal>
      )}
    </div>
  );
}

// ---------- Attendance report: present / late / absent per person ----------
const DEFAULT_WORK_DAYS = [0, 1, 2, 3, 4]; // Sunday → Thursday (Friday and Saturday off)
const DAY_NAMES = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
function lateCutoff(settings) {
  const [h, m] = String(settings?.late_after || "11:00").split(":").map(Number);
  return { h: isNaN(h) ? 11 : h, m: isNaN(m) ? 0 : m, label: `${String(isNaN(h) ? 11 : h).padStart(2, "0")}:${String(isNaN(m) ? 0 : m).padStart(2, "0")}` };
}
function workDaysOf(settings) { return Array.isArray(settings?.work_days) && settings.work_days.length ? settings.work_days.map(Number) : DEFAULT_WORK_DAYS; }
function attendanceStats(attendance, userId, range, settings) {
  const cut = lateCutoff(settings), wd = workDaysOf(settings);
  const firstByDay = {};
  const mineAll = attendance.filter((a) => a.userId === userId);
  const firstEver = mineAll.reduce((m, a) => (!m || new Date(a.checkedInAt) < m ? new Date(a.checkedInAt) : m), null);
  const startKey = firstEver ? dateKey(firstEver.toISOString()) : null; // missed days count only after their first check-in
  mineAll.forEach((a) => {
    const d = new Date(a.checkedInAt), k = dateKey(a.checkedInAt);
    if (d < range[0] || d >= range[1]) return;
    if (!firstByDay[k] || d < new Date(firstByDay[k])) firstByDay[k] = a.checkedInAt;
  });
  const now = new Date();
  const days = [];
  for (let d = new Date(range[0].getFullYear(), range[0].getMonth(), range[0].getDate()); d < range[1] && d <= now; d = new Date(d.getFullYear(), d.getMonth(), d.getDate() + 1)) {
    const k = dateKey(d.toISOString()); // local (Cairo) day
    const isWork = wd.includes(d.getDay());
    const inAt = firstByDay[k] || null;
    const t = inAt ? new Date(inAt) : null;
    const late = t ? t.getHours() * 60 + t.getMinutes() > cut.h * 60 + cut.m : false;
    const todayBeforeCut = k === todayKey() && now.getHours() * 60 + now.getMinutes() <= cut.h * 60 + cut.m;
    if (!isWork && !inAt) continue;
    if (!inAt && (!startKey || k < startKey)) continue;
    days.push({ k, d: new Date(d), inAt, late, absent: isWork && !inAt && !todayBeforeCut, offDay: !isWork });
  }
  const present = days.filter((x) => x.inAt);
  const mins = present.map((x) => { const t = new Date(x.inAt); return t.getHours() * 60 + t.getMinutes(); });
  const avg = mins.length ? Math.round(mins.reduce((a, b) => a + b, 0) / mins.length) : null;
  return {
    days, present: present.length, late: present.filter((x) => x.late).length, onTime: present.filter((x) => !x.late).length,
    absent: days.filter((x) => x.absent).length, workDays: days.filter((x) => !x.offDay).length,
    avg: avg === null ? "—" : `${String(Math.floor(avg / 60)).padStart(2, "0")}:${String(avg % 60).padStart(2, "0")}`,
  };
}
function AttendanceReport({ attendance, people, settings, title = "Attendance", fixedPersonId, storageKey = "attendance", onAdminSet }) {
  const [fv, setF, resetF, setAllF] = useFilters(storageKey, { when: { p: "month" }, person: "", show: "" });
  const [openId, setOpenId] = useState(fixedPersonId || null);
  const cut = lateCutoff(settings);
  const range = dateRangeOf(fv.when) || [new Date(2024, 0, 1), new Date(Date.now() + MS_DAY)];
  const list = (fixedPersonId ? people.filter((u) => u.id === fixedPersonId) : people.filter((u) => !fv.person || u.id === fv.person))
    .map((u) => ({ u, st: attendanceStats(attendance, u.id, range, settings) }))
    .filter((r) => !fv.show || (fv.show === "late" ? r.st.late > 0 : fv.show === "absent" ? r.st.absent > 0 : r.st.late === 0 && r.st.absent === 0))
    .sort((a, b) => b.st.late - a.st.late || b.st.absent - a.st.absent || a.u.name.localeCompare(b.u.name));
  const tot = list.reduce((s, r) => ({ present: s.present + r.st.present, late: s.late + r.st.late, absent: s.absent + r.st.absent }), { present: 0, late: 0, absent: 0 });
  const single = fixedPersonId || list.length === 1;
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", flexWrap: "wrap", gap: 6 }}>
        <div style={{ fontWeight: 700, fontSize: 16, color: COLORS.navy }}>{title}</div>
        <div style={{ fontSize: 12, color: COLORS.textMuted }}>Late = check-in after {cut.label} · days off: {DAY_NAMES.filter((_, i) => !workDaysOf(settings).includes(i)).join(", ")}</div>
      </div>
      <FilterBar id={storageKey} values={fv} set={setF} reset={resetF} setAll={setAllF} count={list.length} noun={list.length === 1 ? "person" : "people"}
        defs={[
          { id: "when", label: "Period", type: "date", primary: true },
          { id: "person", label: "Person", type: "select", primary: true, all: "Everyone", options: fixedPersonId || people.length < 2 ? [] : opt(people, "id", "name") },
          { id: "show", label: "Show", type: "select", primary: true, all: "Everyone", hidden: !!fixedPersonId || people.length < 2, options: [{ id: "late", label: "Came late" }, { id: "absent", label: "Missed days" }, { id: "perfect", label: "Always on time" }] },
        ]} />
      <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
        <FinStat label="Days present" value={tot.present} />
        <FinStat label={`Late (after ${cut.label})`} value={tot.late} tone={tot.late ? "danger" : undefined} />
        <FinStat label="Missed work days" value={tot.absent} tone={tot.absent ? "danger" : undefined} />
      </div>
      {list.map(({ u, st }) => {
        const open = single || openId === u.id;
        return (
          <div key={u.id} className="card" style={{ background: "#fff", border: `1px solid ${COLORS.border}`, overflow: "hidden" }}>
            <button onClick={() => setOpenId(open && !single ? null : u.id)} style={{ width: "100%", display: "flex", alignItems: "center", gap: 10, padding: "12px 14px", border: "none", background: "none", cursor: single ? "default" : "pointer", textAlign: "left", flexWrap: "wrap" }}>
              <div className="avatar" style={{ width: 34, height: 34 }}>{initials(u.name)}</div>
              <div style={{ flex: "1 1 140px", minWidth: 0 }}>
                <div style={{ fontWeight: 700, color: COLORS.navy, fontSize: 14 }}>{u.name}</div>
                <div style={{ fontSize: 12, color: COLORS.textMuted }}>Average check-in {st.avg}</div>
              </div>
              {[["Present", st.present, COLORS.navy], ["On time", st.onTime, COLORS.success], ["Late", st.late, st.late ? COLORS.danger : COLORS.textMuted], ["Missed", st.absent, st.absent ? COLORS.danger : COLORS.textMuted]].map(([l, v, c]) => (
                <div key={l} style={{ textAlign: "center", minWidth: 58 }}><div style={{ fontWeight: 800, fontSize: 18, color: c }}>{v}</div><div style={{ fontSize: 11, color: COLORS.textMuted }}>{l}</div></div>
              ))}
            </button>
            {open && (
              <div style={{ borderTop: `1px solid ${COLORS.border}`, padding: 12, display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(118px, 1fr))", gap: 6 }}>
                {st.days.length === 0 && <div style={{ fontSize: 12.5, color: COLORS.textMuted }}>No work days in this period.</div>}
                {onAdminSet && <div style={{ gridColumn: "1 / -1", fontSize: 11.5, color: COLORS.textMuted }}>Admin / CEO: tap a day to change or remove the check-in time.</div>}
                {[...st.days].reverse().map((x) => (
                  <div key={x.k} onClick={onAdminSet ? () => {
                      const cur = x.inAt ? new Date(x.inAt).toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" }) : "";
                      const v = window.prompt(`${u.name} · ${DAY_NAMES[x.d.getDay()]} ${x.d.getDate()}/${x.d.getMonth() + 1}\nCheck-in time (HH:MM, 24h). Leave empty to remove the check-in.`, cur);
                      if (v === null) return;
                      const t = v.trim();
                      if (t && !/^([01]?\d|2[0-3]):[0-5]\d$/.test(t)) { window.alert("Write the time like 09:45"); return; }
                      Promise.resolve(onAdminSet(u.id, x.d, t || null)).catch((e) => window.alert(e.message || "Could not save the check-in"));
                    } : undefined}
                    title={onAdminSet ? "Change check-in" : undefined}
                    style={{ borderRadius: 10, padding: "6px 8px", fontSize: 12, cursor: onAdminSet ? "pointer" : "default", background: x.absent ? "#FCEBEB" : x.late ? "#FBF1E6" : x.inAt ? "#E6F4EA" : COLORS.cream, color: x.absent ? COLORS.danger : COLORS.text }}>
                    <div style={{ fontWeight: 700 }}>{DAY_NAMES[x.d.getDay()]} {x.d.getDate()}/{x.d.getMonth() + 1}</div>
                    <div>{x.inAt ? `${new Date(x.inAt).toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" })}${x.late ? " · late" : ""}${x.offDay ? " · day off" : ""}` : x.absent ? "Missed" : "—"}</div>
                  </div>
                ))}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

// A small inline panel listing clients, used by both the Dashboard and Reports drilldowns.
function MiniClientList({ title, clientList, users, onOpenClient, onClose }) {
  return (
    <div style={{ background: "#fff", border: `1px solid ${COLORS.border}`, borderRadius: 14, padding: 14, marginTop: 10 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
        <div style={{ fontWeight: 700, fontSize: 13.5, color: COLORS.navy }}>{title} ({clientList.length})</div>
        <button onClick={onClose} style={{ border: "none", background: "none", cursor: "pointer" }}><X size={16} /></button>
      </div>
      {clientList.length === 0 ? (
        <div style={{ color: COLORS.textMuted, fontSize: 12.5 }}>No clients match.</div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
          {clientList.map((c) => {
            const owner = users.find((u) => u.id === c.assignedTo);
            return (
              <div key={c.id} onClick={() => onOpenClient(c)} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10, padding: "8px 10px", border: `1px solid ${COLORS.border}`, borderRadius: 10, cursor: "pointer" }}>
                <div style={{ minWidth: 0 }}>
                  <div style={{ fontWeight: 600, fontSize: 13, color: COLORS.text, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{c.name}</div>
                  <div style={{ fontSize: 11.5, color: COLORS.textMuted }}>{owner?.name || "Unassigned"} · {c.phone}</div>
                </div>
                <ClientStageBadge stage={c.stage} />
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

// A single clickable stat tile.
function StatTile({ label, count, onClick, active }) {
  return (
    <button onClick={onClick} style={{
      textAlign: "left", cursor: "pointer", border: `1px solid ${active ? COLORS.navy : COLORS.border}`,
      background: active ? COLORS.creamDark : "#fff", borderRadius: 14, padding: "12px 14px", minWidth: 140,
    }}>
      <div style={{ fontSize: 22, fontWeight: 800, color: COLORS.navy }}>{count}</div>
      <div style={{ fontSize: 12, color: COLORS.textMuted, marginTop: 2 }}>{label}</div>
    </button>
  );
}

function Dashboard({ clients, activity, users, visibleSalesIds, onOpenClient, attendance, attendanceSettings }) {
  const [metric, setMetric] = useState(null); // "meetings" | "stage" | "delayed" | "long_term" | "checked_in" | "not_checked_in"
  const [stageFilter, setStageFilter] = useState("");
  const [salesFilter, setSalesFilter] = useState("");

  const scoped = clients.filter((c) => visibleSalesIds.includes(c.assignedTo));
  const meetingsToday = scoped.filter((c) => c.meetingAt && isToday(c.meetingAt) && c.stage === "meeting_generated");
  const delayedLeads = scoped.filter((c) => isClientDelayed(c, activity));
  const longTermLeads = scoped.filter((c) => c.stage === LONG_TERM_STAGE);
  const dashboardStages = PIPELINE_STAGES.concat(EXCEPTION_STAGES);
  const salesOptions = users.filter((u) => visibleSalesIds.includes(u.id));

  const trackedStaff = users.filter((u) => visibleSalesIds.includes(u.id) && ["sales_agent", "team_leader", "sales_manager"].includes(u.role));
  const checkedInTodayIds = new Set(attendance.filter((a) => isToday(a.checkedInAt)).map((a) => a.userId));
  const checkedInStaff = trackedStaff.filter((u) => checkedInTodayIds.has(u.id));
  const notCheckedInStaff = trackedStaff.filter((u) => !checkedInTodayIds.has(u.id));

  let drillList = [];
  let drillTitle = "";
  if (metric === "meetings") { drillList = meetingsToday; drillTitle = "Meetings today"; }
  else if (metric === "delayed") { drillList = delayedLeads; drillTitle = "Delayed leads"; }
  else if (metric === "long_term") { drillList = longTermLeads; drillTitle = "Long Term"; }
  else if (metric === "stage" && stageFilter) {
    drillList = scoped.filter((c) => c.stage === stageFilter && (!salesFilter || c.assignedTo === salesFilter));
    drillTitle = STAGE_LABEL[stageFilter];
  }

  const openStage = (stageId) => { setMetric("stage"); setStageFilter(stageId); setSalesFilter(""); };

  return (
    <div>
      <div style={{ fontWeight: 600, fontSize: 16, color: COLORS.navy, marginBottom: 14 }}>Dashboard</div>

      <div style={{ display: "flex", flexWrap: "wrap", gap: 10, marginBottom: 6 }}>
        <StatTile label="Meetings today" count={meetingsToday.length} active={metric === "meetings"} onClick={() => setMetric(metric === "meetings" ? null : "meetings")} />
        <StatTile label="Delayed leads (no update 7+ days)" count={delayedLeads.length} active={metric === "delayed"} onClick={() => setMetric(metric === "delayed" ? null : "delayed")} />
        <StatTile label="Long Term" count={longTermLeads.length} active={metric === "long_term"} onClick={() => setMetric(metric === "long_term" ? null : "long_term")} />
        <StatTile label="Checked in today" count={checkedInStaff.length} active={metric === "checked_in"} onClick={() => setMetric(metric === "checked_in" ? null : "checked_in")} />
        <StatTile label="Not checked in yet" count={notCheckedInStaff.length} active={metric === "not_checked_in"} onClick={() => setMetric(metric === "not_checked_in" ? null : "not_checked_in")} />
      </div>

      {(metric === "checked_in" || metric === "not_checked_in") && (
        <div style={{ background: "#fff", border: `1px solid ${COLORS.border}`, borderRadius: 14, padding: 14, marginTop: 4, marginBottom: 10 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
            <div style={{ fontWeight: 700, fontSize: 13.5, color: COLORS.navy }}>
              {metric === "checked_in" ? `Checked in today (${checkedInStaff.length})` : `Not checked in yet (${notCheckedInStaff.length})`}
            </div>
            <button onClick={() => setMetric(null)} style={{ border: "none", background: "none", cursor: "pointer" }}><X size={16} /></button>
          </div>
          {(metric === "checked_in" ? checkedInStaff : notCheckedInStaff).length === 0 ? (
            <div style={{ color: COLORS.textMuted, fontSize: 12.5 }}>Nobody here.</div>
          ) : (
            <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
              {(metric === "checked_in" ? checkedInStaff : notCheckedInStaff).map((u) => {
                const a = attendance.find((row) => row.userId === u.id && isToday(row.checkedInAt));
                return (
                  <div key={u.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10, padding: "8px 10px", border: `1px solid ${COLORS.border}`, borderRadius: 10 }}>
                    <div style={{ fontWeight: 600, fontSize: 13, color: COLORS.text }}>{u.name} <span style={{ fontWeight: 400, color: COLORS.textMuted }}>· {ROLE_LABEL[u.role]}</span></div>
                    {a && <div style={{ fontSize: 11.5, color: COLORS.textMuted }}>{formatDateTime(a.checkedInAt)}</div>}
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      <div style={{ fontSize: 12.5, fontWeight: 600, color: COLORS.textMuted, margin: "16px 0 8px" }}>Clients per stage</div>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 10 }}>
        {dashboardStages.map((s) => (
          <StatTile
            key={s.id}
            label={s.label}
            count={scoped.filter((c) => c.stage === s.id).length}
            active={metric === "stage" && stageFilter === s.id}
            onClick={() => (metric === "stage" && stageFilter === s.id ? setMetric(null) : openStage(s.id))}
          />
        ))}
      </div>

      {metric === "stage" && stageFilter && (
        <div style={{ marginTop: 10, display: "flex", alignItems: "center", gap: 8 }}>
          <span style={{ fontSize: 12.5, color: COLORS.textMuted }}>Filter by sales person:</span>
          <Sel style={{ ...inputStyle, width: 220 }} value={salesFilter} onChange={(e) => setSalesFilter(e.target.value)}>
            <option value="">All</option>
            {salesOptions.map((u) => <option key={u.id} value={u.id}>{u.name}</option>)}
          </Sel>
        </div>
      )}

      {metric && (
        <MiniClientList title={drillTitle} clientList={drillList} users={users} onOpenClient={onOpenClient} onClose={() => setMetric(null)} />
      )}

      <div style={{ fontSize: 12.5, fontWeight: 600, color: COLORS.textMuted, margin: "16px 0 8px" }}>Attendance log — everyone</div>
      <div style={{ marginTop: 14 }}><AttendanceReport attendance={attendance} people={users.filter((u) => visibleSalesIds.includes(u.id) && !["pending", "admin", "ceo"].includes(u.role))} settings={attendanceSettings} title="Team attendance" storageKey="attendance:dash" /></div>
    </div>
  );
}

function MiniUnitList({ title, unitList, onOpenUnit, onClose }) {
  return (
    <div style={{ background: "#fff", border: `1px solid ${COLORS.border}`, borderRadius: 14, padding: 14, marginTop: 10 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
        <div style={{ fontWeight: 700, fontSize: 13.5, color: COLORS.navy }}>{title} ({unitList.length})</div>
        <button onClick={onClose} style={{ border: "none", background: "none", cursor: "pointer" }}><X size={16} /></button>
      </div>
      {unitList.length === 0 ? (
        <div style={{ color: COLORS.textMuted, fontSize: 12.5 }}>No units match.</div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
          {unitList.map((u) => (
            <div key={u.id} onClick={() => onOpenUnit(u)} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10, padding: "8px 10px", border: `1px solid ${COLORS.border}`, borderRadius: 10, cursor: "pointer" }}>
              <div style={{ fontWeight: 600, fontSize: 13, color: COLORS.text }}>Unit {u.unitNumber}</div>
              <div style={{ fontSize: 11.5, color: COLORS.textMuted }}>{formatDate(u.updatedAt)}</div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function ReportsTab({ clients, activity, users, units, visibleSalesIds, onOpenClient, onOpenUnit, attendance, attendanceSettings }) {
  const [personId, setPersonId] = useState("");
  const [metric, setMetric] = useState(null);
  const [stageFilter, setStageFilter] = useState("");

  const reportable = users.filter((u) => visibleSalesIds.includes(u.id) && ["sales_agent", "team_leader", "sales_manager"].includes(u.role));

  if (!personId) {
    return (
      <div>
        <div style={{ fontWeight: 600, fontSize: 16, color: COLORS.navy, marginBottom: 14 }}>Reports</div>
        <FunnelReport clients={clients} activity={activity} users={users} visibleSalesIds={visibleSalesIds} />
        <div style={{ fontWeight: 600, fontSize: 13.5, color: COLORS.navy, margin: "4px 0 10px" }}>One person's report</div>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 10 }}>
          {reportable.map((u) => (
            <button key={u.id} onClick={() => setPersonId(u.id)} style={{ textAlign: "left", cursor: "pointer", border: `1px solid ${COLORS.border}`, background: "#fff", borderRadius: 14, padding: "12px 14px", minWidth: 180, display: "flex", alignItems: "center", gap: 10 }}>
              <div style={{ width: 34, height: 34, borderRadius: "50%", background: COLORS.navy, color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 700, fontSize: 13 }}>{initials(u.name)}</div>
              <div>
                <div style={{ fontWeight: 600, fontSize: 13.5, color: COLORS.text }}>{u.name}</div>
                <div style={{ fontSize: 11.5, color: COLORS.textMuted }}>{ROLE_LABEL[u.role]}</div>
              </div>
            </button>
          ))}
          {reportable.length === 0 && <div style={{ color: COLORS.textMuted, fontSize: 13 }}>No team members yet.</div>}
        </div>
      </div>
    );
  }

  const person = users.find((u) => u.id === personId);
  const mine = clients.filter((c) => c.assignedTo === personId);
  const untouched3d = mine.filter((c) => !TERMINAL_STAGES.includes(c.stage) && c.stage !== LONG_TERM_STAGE && Date.now() - new Date(clientLastActivityAt(c, activity)).getTime() > REPORT_STALE_DAYS * MS_DAY);
  const addedToday = mine.filter((c) => isToday(c.createdAt));
  const actionTodayIds = new Set(activity.filter((a) => isToday(a.changedAt) && mine.some((c) => c.id === a.clientId)).map((a) => a.clientId));
  const actionToday = mine.filter((c) => actionTodayIds.has(c.id));
  const meetingScheduledToday = mine.filter((c) => c.meetingAt && isToday(c.meetingAt) && c.stage === "meeting_generated");
  const meetingDoneTodayIds = new Set(activity.filter((a) => isToday(a.changedAt) && ((a.action === "quick_reply" && a.fieldName === "meeting_done") || (a.action === "stage_change" && (a.newValue === "meeting_done" || (a.oldValue === "meeting_generated" && a.newValue !== "meeting_generated"))))).map((a) => a.clientId));
  const meetingDoneToday = mine.filter((c) => meetingDoneTodayIds.has(c.id));

  const myUnitsAll = units.filter((u) => u.salesIds.includes(personId));
  const unitsAddedToday = myUnitsAll.filter((u) => isToday(u.createdAt));
  const unitsEditedToday = myUnitsAll.filter((u) => isToday(u.updatedAt) && u.updatedAt !== u.createdAt);

  let drillList = [];
  let drillTitle = "";
  let drillIsUnits = false;
  if (metric === "total") { drillList = mine; drillTitle = "All clients"; }
  else if (metric === "untouched3d") { drillList = untouched3d; drillTitle = `Untouched ${REPORT_STALE_DAYS}+ days`; }
  else if (metric === "addedToday") { drillList = addedToday; drillTitle = "Added today"; }
  else if (metric === "actionToday") { drillList = actionToday; drillTitle = "Any action today"; }
  else if (metric === "meetingScheduledToday") { drillList = meetingScheduledToday; drillTitle = "Meeting scheduled today"; }
  else if (metric === "meetingDoneToday") { drillList = meetingDoneToday; drillTitle = "Meeting done today"; }
  else if (metric === "stage" && stageFilter) { drillList = mine.filter((c) => c.stage === stageFilter); drillTitle = STAGE_LABEL[stageFilter]; }
  else if (metric === "unitsAddedToday") { drillList = unitsAddedToday; drillTitle = "Units added today"; drillIsUnits = true; }
  else if (metric === "unitsEditedToday") { drillList = unitsEditedToday; drillTitle = "Units edited today"; drillIsUnits = true; }
  else if (metric === "unitsTotal") { drillList = myUnitsAll; drillTitle = "Total units"; drillIsUnits = true; }

  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 14 }}>
        <button onClick={() => { setPersonId(""); setMetric(null); }} style={{ border: `1px solid ${COLORS.border}`, background: "#fff", padding: "7px 12px", borderRadius: 10, cursor: "pointer", fontSize: 12.5 }}>← All people</button>
        <div style={{ fontWeight: 600, fontSize: 16, color: COLORS.navy }}>{person?.name} <span style={{ color: COLORS.gold, fontSize: 13 }}>· {ROLE_LABEL[person?.role]}</span></div>
      </div>

      <div style={{ display: "flex", flexWrap: "wrap", gap: 10 }}>
        <StatTile label="Total clients" count={mine.length} active={metric === "total"} onClick={() => setMetric(metric === "total" ? null : "total")} />
        <StatTile label={`Untouched ${REPORT_STALE_DAYS}+ days`} count={untouched3d.length} active={metric === "untouched3d"} onClick={() => setMetric(metric === "untouched3d" ? null : "untouched3d")} />
        <StatTile label="Added today" count={addedToday.length} active={metric === "addedToday"} onClick={() => setMetric(metric === "addedToday" ? null : "addedToday")} />
        <StatTile label="Any action today" count={actionToday.length} active={metric === "actionToday"} onClick={() => setMetric(metric === "actionToday" ? null : "actionToday")} />
        <StatTile label="Meeting scheduled today" count={meetingScheduledToday.length} active={metric === "meetingScheduledToday"} onClick={() => setMetric(metric === "meetingScheduledToday" ? null : "meetingScheduledToday")} />
        <StatTile label="Meeting done today" count={meetingDoneToday.length} active={metric === "meetingDoneToday"} onClick={() => setMetric(metric === "meetingDoneToday" ? null : "meetingDoneToday")} />
      </div>

      <div style={{ fontSize: 12.5, fontWeight: 600, color: COLORS.textMuted, margin: "16px 0 8px" }}>Clients per stage</div>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 10 }}>
        {PIPELINE_STAGES.concat(EXCEPTION_STAGES).map((s) => (
          <StatTile
            key={s.id}
            label={s.label}
            count={mine.filter((c) => c.stage === s.id).length}
            active={metric === "stage" && stageFilter === s.id}
            onClick={() => (metric === "stage" && stageFilter === s.id ? setMetric(null) : (setMetric("stage"), setStageFilter(s.id)))}
          />
        ))}
      </div>

      <div style={{ fontSize: 12.5, fontWeight: 600, color: COLORS.textMuted, margin: "16px 0 8px" }}>Units</div>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 10 }}>
        <StatTile label="Total units" count={myUnitsAll.length} active={metric === "unitsTotal"} onClick={() => setMetric(metric === "unitsTotal" ? null : "unitsTotal")} />
        <StatTile label="Units added today" count={unitsAddedToday.length} active={metric === "unitsAddedToday"} onClick={() => setMetric(metric === "unitsAddedToday" ? null : "unitsAddedToday")} />
        <StatTile label="Units edited today" count={unitsEditedToday.length} active={metric === "unitsEditedToday"} onClick={() => setMetric(metric === "unitsEditedToday" ? null : "unitsEditedToday")} />
      </div>

      {metric && drillIsUnits && (
        <MiniUnitList title={drillTitle} unitList={drillList} onOpenUnit={onOpenUnit} onClose={() => setMetric(null)} />
      )}
      {metric && !drillIsUnits && (
        <MiniClientList title={drillTitle} clientList={drillList} users={users} onOpenClient={onOpenClient} onClose={() => setMetric(null)} />
      )}

      <div style={{ fontSize: 12.5, fontWeight: 600, color: COLORS.textMuted, margin: "16px 0 8px" }}>Attendance</div>
      <div style={{ marginTop: 14 }}><AttendanceReport attendance={attendance} people={users} settings={attendanceSettings} fixedPersonId={personId} title="Attendance" storageKey="attendance:person" /></div>
    </div>
  );
}

// ---------- Main app ----------
// =====================================================================
// ---------- FINANCE: pure calculation engine ----------
// Everything money-related is derived from three facts in the database:
//   * deal_agents   (who sold which deal, and their % of it)
//   * deal_rates    (frozen chain: seller -> managers, % per tier)
//   * finance_transactions (cash in / out, the single ledger)
// Nothing derived is stored, so tiers, balances and "owed" amounts
// always reflect the latest data (incl. retroactive tier upgrades).
// =====================================================================
const FIN_ADMIN_ROLES = ["admin", "ceo"];
const isFinanceAdmin = (p) => !!p && FIN_ADMIN_ROLES.includes(p.role);

const round2 = (n) => Math.round((Number(n) || 0) * 100) / 100;
const num = (v) => (v === "" || v === null || v === undefined ? 0 : Number(v) || 0);

function pad2(n) { return String(n).padStart(2, "0"); }
function quarterKeyOf(dateLike) {
  const d = new Date(dateLike);
  return `${d.getFullYear()}-Q${Math.floor(d.getMonth() / 3) + 1}`;
}
function currentQuarterKey() { return quarterKeyOf(new Date()); }
function quarterBounds(key) {
  const [y, q] = key.split("-Q").map(Number);
  const from = new Date(y, (q - 1) * 3, 1);
  const to = new Date(y, q * 3, 1); // exclusive
  return { from, to };
}
function quarterLabel(key) {
  const [y, q] = key.split("-Q");
  const months = ["Jan–Mar", "Apr–Jun", "Jul–Sep", "Oct–Dec"][Number(q) - 1];
  return `Q${q} ${y} (${months})`;
}
function shiftQuarter(key, delta) {
  const [y, q] = key.split("-Q").map(Number);
  const idx = y * 4 + (q - 1) + delta;
  return `${Math.floor(idx / 4)}-Q${(idx % 4) + 1}`;
}
function monthKeyOf(dateLike) {
  const d = new Date(dateLike);
  return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}`;
}
function currentMonthKey() { return monthKeyOf(new Date()); }
// Salaries are paid after the month ends (October's salary is due 1 November);
// fixed monthly items (rent…) are paid in advance (November's rent is due 1 November).
function shiftMonth(key, delta) {
  const [y, m] = key.split("-").map(Number);
  const d = new Date(y, m - 1 + delta, 1);
  return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}`;
}
function monthStart(key) {
  const [y, m] = key.split("-").map(Number);
  return new Date(y, m - 1, 1);
}
const salaryDueDate = (monthKey) => monthStart(shiftMonth(monthKey, 1));
const fixedDueDate = (monthKey) => monthStart(monthKey);
function monthLabel(key) {
  const [y, m] = key.split("-").map(Number);
  return new Date(y, m - 1, 1).toLocaleDateString("en-US", { month: "long", year: "numeric" });
}

// rates[i] belongs to tier i. Shorter arrays reuse their last value.
function rateAt(rates, tierIdx) {
  if (!rates || rates.length === 0) return 0;
  return num(rates[Math.min(tierIdx, rates.length - 1)]);
}
function tierIndexFor(pct, thresholds) {
  let idx = 0;
  (thresholds || [0]).forEach((t, i) => { if (pct >= num(t)) idx = i; });
  return idx;
}
function tierLabel(idx, thresholds) {
  if (!idx) return "Base";
  return `≥${num((thresholds || [])[idx])}%`;
}

// Walk up the org chart: [person, manager, manager's manager, ...]
function managerChain(users, userId) {
  const chain = [];
  const seen = new Set();
  let cur = users.find((u) => u.id === userId);
  while (cur && !seen.has(cur.id) && chain.length < 20) {
    chain.push(cur);
    seen.add(cur.id);
    cur = cur.managerId ? users.find((u) => u.id === cur.managerId) : null;
  }
  return chain;
}

function groupBy(list, keyFn) {
  const out = {};
  list.forEach((x) => {
    const k = keyFn(x);
    (out[k] = out[k] || []).push(x);
  });
  return out;
}

/**
 * Core computation.
 * @returns {
 *   lines: [{ dealId, beneficiaryId, entitled, base, paid, remaining, uplift, detail:[...] }],
 *   achievement(agentId, qKey) -> amount counted toward target,
 *   achievementPct(agentId, qKey), tierOf(agentId, qKey),
 *   collectedByDeal: {dealId: amount},
 *   companyShareByDeal: {dealId: amount}   // only meaningful when all rates are visible (admins)
 * }
 */
// ---- Deal sides: Origin can represent the buyer, the seller, or both.
// Each side has its own commission and its own team (shares add up to 100 per side).
const SIDE_LABEL = { buyer: "Buyer side", seller: "Seller side" };
// Rent deals: buyer side = tenant, seller side = landlord. Same commission scheme as sales.
const isRentDeal = (d) => !!d && d.deal_type === "rent";
const partyName = (dealType, side) => (dealType === "rent" ? (side === "buyer" ? "tenant" : "landlord") : side);
const sideLabelFor = (dealType, side) => (dealType === "rent" ? (side === "buyer" ? "Tenant side" : "Landlord side") : SIDE_LABEL[side]);
const dealSides = (d) => (d && d.sides === "both" ? ["buyer", "seller"] : [d && d.sides === "seller" ? "seller" : "buyer"]);
const sideCommission = (d, side) => {
  const b = num(d.commission_buyer), sl = num(d.commission_seller);
  if (b + sl <= 0) return dealSides(d).length === 1 && dealSides(d)[0] === side ? num(d.commission_total) : 0;
  return side === "buyer" ? b : sl;
};
// How an amount collected on a deal splits between its sides
function sideAmounts(d, amount, side) {
  if (side) return { [side]: num(amount) };
  const sides = dealSides(d);
  if (sides.length === 1) return { [sides[0]]: num(amount) };
  const b = sideCommission(d, "buyer"), sl = sideCommission(d, "seller");
  const wB = b + sl > 0 ? b / (b + sl) : 0.5;
  return { buyer: num(amount) * wB, seller: num(amount) * (1 - wB) };
}
const agentSide = (a) => a.side || "buyer";

function computeFinance({ deals, dealAgents, dealRates, txns, targets, thresholds, charityPct = 0 }) {
  const approved = new Set(deals.filter((d) => d.status === "approved").map((d) => d.id));
  // money collected on reservations counts toward targets (in the quarter it came in); payouts wait for the transfer
  const counted = new Set(deals.filter((d) => d.status === "approved" || d.status === "reserved").map((d) => d.id));
  const dealById = Object.fromEntries(deals.map((d) => [d.id, d]));
  const agentsByDeal = groupBy(dealAgents, (a) => a.deal_id);
  // one rate row per (deal, seller, beneficiary), even if duplicates slip in
  const uniqueRates = Object.values(Object.fromEntries(dealRates.map((r) => [`${r.deal_id}|${r.agent_id}|${r.beneficiary_id}`, r])));
  const ratesByDealAgent = groupBy(uniqueRates, (r) => `${r.deal_id}|${r.agent_id}`);
  const collections = txns.filter((t) => t.kind === "commission_in" && t.deal_id);

  const collectedByDeal = {};
  const ach = {}; // agentId -> qKey -> amount
  collections.forEach((c) => {
    collectedByDeal[c.deal_id] = round2((collectedByDeal[c.deal_id] || 0) + num(c.amount));
    if (!counted.has(c.deal_id)) return;
    const q = quarterKeyOf(c.occurred_at);
    const bySide = sideAmounts(dealById[c.deal_id], c.amount, c.side);
    (agentsByDeal[c.deal_id] || []).forEach((a) => {
      ach[a.agent_id] = ach[a.agent_id] || {};
      ach[a.agent_id][q] = (ach[a.agent_id][q] || 0) + (num(bySide[agentSide(a)]) * num(a.split_pct)) / 100;
    });
  });

  const achievement = (agentId, q) => round2((ach[agentId] && ach[agentId][q]) || 0);
  const achievementPct = (agentId, q) => {
    const target = num(targets[agentId]);
    if (!target) return 0;
    return (achievement(agentId, q) / target) * 100;
  };
  const tierOf = (agentId, q) => (num(targets[agentId]) ? tierIndexFor(achievementPct(agentId, q), thresholds) : 0);

  const lines = {};
  const lineFor = (dealId, beneficiaryId) => {
    const k = `${dealId}|${beneficiaryId}`;
    if (!lines[k]) lines[k] = { dealId, beneficiaryId, entitled: 0, base: 0, paid: 0, detail: [] };
    return lines[k];
  };

  collections.forEach((c) => {
    if (!counted.has(c.deal_id)) return; // reserved deals too: sales can be paid from what came in
    const q = quarterKeyOf(c.occurred_at);
    const bySide = sideAmounts(dealById[c.deal_id], c.amount, c.side);
    (agentsByDeal[c.deal_id] || []).forEach((a) => {
      const portion = (num(bySide[agentSide(a)]) * num(a.split_pct)) / 100;
      const tier = tierOf(a.agent_id, q);
      (ratesByDealAgent[`${c.deal_id}|${a.agent_id}`] || []).forEach((r) => {
        const rate = rateAt(r.rates, tier);
        const line = lineFor(c.deal_id, r.beneficiary_id);
        const amount = (portion * rate) / 100;
        line.entitled += amount;
        line.base += (portion * rateAt(r.rates, 0)) / 100;
        line.detail.push({ agentId: a.agent_id, side: agentSide(a), level: r.level, quarter: q, tier, rate, portion, amount, txId: c.id });
      });
    });
  });

  txns.filter((t) => t.kind === "payout" && t.deal_id && t.beneficiary_id).forEach((p) => {
    lineFor(p.deal_id, p.beneficiary_id).paid += num(p.amount);
  });

  const out = Object.values(lines).map((l) => ({
    ...l,
    entitled: round2(l.entitled),
    base: round2(l.base),
    paid: round2(l.paid),
    remaining: round2(l.entitled - l.paid),
    uplift: round2(l.entitled - l.base),
  }));

  // "Floos Rabna": automatic % of each collection moved to its own account (company share only)
  const charityByDeal = {};
  txns.filter((t) => t.kind === "transfer" && t.direction === "out" && t.source_tx_id && t.deal_id).forEach((t) => {
    charityByDeal[t.deal_id] = round2((charityByDeal[t.deal_id] || 0) + num(t.amount));
  });
  // Reserved deals: Floos Rabna is set aside on paper and moves only when the deal is done
  const charityPendingByDeal = {};
  deals.filter((d) => d.status === "reserved").forEach((d) => {
    const pend = round2(num(collectedByDeal[d.id]) * num(charityPct) / 100 - num(charityByDeal[d.id]));
    if (pend > 0) { charityPendingByDeal[d.id] = pend; charityByDeal[d.id] = round2(num(charityByDeal[d.id]) + pend); }
  });

  const companyShareByDeal = {};
  Object.keys(collectedByDeal).forEach((dealId) => {
    if (!counted.has(dealId)) return;
    const distributed = out.filter((l) => l.dealId === dealId).reduce((s, l) => s + l.entitled, 0);
    companyShareByDeal[dealId] = round2(collectedByDeal[dealId] - distributed - (charityByDeal[dealId] || 0));
  });

  // What's still to come on reserved / partly collected deals — estimated at each seller's tier this quarter
  const qNow = currentQuarterKey();
  const collectedSide = {};
  collections.forEach((c) => {
    const by = sideAmounts(dealById[c.deal_id], c.amount, c.side);
    const o = (collectedSide[c.deal_id] = collectedSide[c.deal_id] || { buyer: 0, seller: 0 });
    o.buyer += num(by.buyer); o.seller += num(by.seller);
  });
  const expectedByDeal = {};
  deals.filter((d) => counted.has(d.id)).forEach((d) => {
    const got = collectedSide[d.id] || { buyer: 0, seller: 0 };
    const left = { buyer: Math.max(0, sideCommission(d, "buyer") - got.buyer), seller: Math.max(0, sideCommission(d, "seller") - got.seller) };
    const leftTotal = round2(left.buyer + left.seller);
    const people = {};
    (agentsByDeal[d.id] || []).forEach((a) => {
      const portion = (num(left[agentSide(a)]) * num(a.split_pct)) / 100;
      const tier = tierOf(a.agent_id, qNow);
      (ratesByDealAgent[`${d.id}|${a.agent_id}`] || []).forEach((r) => { people[r.beneficiary_id] = round2((people[r.beneficiary_id] || 0) + (portion * rateAt(r.rates, tier)) / 100); });
    });
    const team = round2(Object.values(people).reduce((x, v) => x + v, 0));
    const charity = round2((leftTotal * num(charityPct)) / 100);
    expectedByDeal[d.id] = { left: leftTotal, people, team, charity, company: round2(leftTotal - team - charity) };
  });

  return { lines: out, achievement, achievementPct, tierOf, collectedByDeal, companyShareByDeal, charityByDeal, charityPendingByDeal, expectedByDeal };
}

// Preview of a pending deal's split using the CURRENT plans (before rates get frozen)
function previewDistribution({ dealAgents, users, commissionRates, amounts, tierOf, quarter, tierCount, charityPct = 0 }) {
  const rows = [];
  const amount = num(amounts.buyer) + num(amounts.seller);
  dealAgents.forEach((a) => {
    const portion = (num(amounts[agentSide(a)]) * num(a.split_pct)) / 100;
    const tier = tierOf ? tierOf(a.agent_id, quarter) : 0;
    managerChain(users, a.agent_id).forEach((person, level) => {
      const plan = commissionRates.find((r) => r.seller_id === a.agent_id && r.beneficiary_id === person.id);
      const rates = plan ? plan.rates : new Array(tierCount || 1).fill(0);
      const rate = rateAt(rates, tier);
      rows.push({ agentId: a.agent_id, side: agentSide(a), beneficiaryId: person.id, level, tier, rate, amount: round2((portion * rate) / 100), missingPlan: !plan });
    });
  });
  const distributed = rows.reduce((s, r) => s + r.amount, 0);
  const charity = round2((num(amount) * num(charityPct)) / 100);
  return { rows, charity, company: round2(num(amount) - distributed - charity) };
}

function accountBalances(accounts, txns, before) {
  const bal = {};
  accounts.forEach((a) => { bal[a.id] = 0; });
  txns.forEach((t) => {
    if (before && new Date(t.occurred_at) >= before) return;
    bal[t.account_id] = round2((bal[t.account_id] || 0) + (t.direction === "in" ? 1 : -1) * num(t.amount));
  });
  return bal;
}

// Balanced 100% split between n people (last one absorbs rounding)
function equalSplits(n) {
  if (n <= 0) return [];
  const each = Math.floor((100 / n) * 100) / 100;
  const arr = new Array(n).fill(each);
  arr[n - 1] = round2(100 - each * (n - 1));
  return arr;
}

// =====================================================================
// ---------- FINANCE: shared UI pieces ----------
