const thNum = { ...thStyle, textAlign: "right" };

function egp(n) {
  const v = round2(n);
  return v.toLocaleString("en-US", { minimumFractionDigits: 0, maximumFractionDigits: 2 });
}
function egpFull(n) { return `${egp(n)} EGP`; }
function todayInput() {
  const d = new Date();
  return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`;
}
function dateInputToIso(v) { return v ? new Date(`${v}T12:00:00`).toISOString() : new Date().toISOString(); }
function isoToDateInput(iso) {
  if (!iso) return "";
  const d = new Date(iso);
  return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`;
}

const dealStatusInfo = (d) => {
  const base = DEAL_STATUS[d && d.status] || DEAL_STATUS.pending;
  if (d && d.status === "reserved" && isRentDeal(d)) return { ...base, label: "Reserved · rental" };
  if (d && d.status === "approved" && isRentDeal(d)) return { ...base, label: "Done · rented" };
  return base;
};
const dealPriceText = (d) => (isRentDeal(d)
  ? `${egp(d.rent_monthly)} EGP / month × ${num(d.lease_months)} months`
  : egpFull(d.sale_price));
const dealShownDate = (d) => (d.status === "approved" && d.transfer_date ? d.transfer_date : d.deal_date);
const DEAL_STATUS = {
  pending: { label: "Waiting for approval", tone: "pending" },
  returned: { label: "Returned for changes", tone: "hold" },
  reserved: { label: "Reserved · promise of sale", tone: "neutral" },
  approved: { label: "Done deal", tone: "active" },
  rejected: { label: "Rejected", tone: "hold" },
  cancelled: { label: "Cancelled", tone: "neutral" },
};
const TX_KIND_LABEL = {
  commission_in: "Commission collected",
  payout: "Commission payout",
  expense: "Expense",
  salary: "Salary",
  transfer: "Transfer",
  adjustment: "Adjustment",
  refund: "Refund",
};

// Numbers roll up when they first appear (e.g. "312,500" counts up from 0)
function CountUp({ value }) {
  const str = String(value ?? "");
  const m = str.match(/^([^0-9-]*)(-?[0-9][0-9,]*\.?[0-9]*)(.*)$/);
  const target = m ? Number(m[2].replace(/,/g, "")) : NaN;
  const [shown, setShown] = useState(isNaN(target) ? str : `${m[1]}0${m[3]}`);
  useEffect(() => {
    if (isNaN(target) || typeof window === "undefined" || window.matchMedia?.("(prefers-reduced-motion: reduce)").matches) { setShown(str); return; }
    const dec = (m[2].split(".")[1] || "").length;
    let raf, t0;
    const step = (t) => {
      if (!t0) t0 = t;
      const p = Math.min(1, (t - t0) / 700), e = 1 - Math.pow(1 - p, 3);
      const v = target * e;
      setShown(p >= 1 ? str : `${m[1]}${v.toLocaleString("en-US", { minimumFractionDigits: dec, maximumFractionDigits: dec })}${m[3]}`);
      if (p < 1) raf = requestAnimationFrame(step);
    };
    raf = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf);
  }, [str]); // eslint-disable-line
  return <>{shown}</>;
}

function FinStat({ label, value, sub, tone, onClick }) {
  const color = tone === "danger" ? COLORS.danger : tone === "success" ? COLORS.success : COLORS.navy;
  return (
    <div onClick={onClick} style={{ ...finCard, padding: "12px 14px", minWidth: 170, flex: "1 1 170px", cursor: onClick ? "pointer" : "default" }}>
      <div style={{ fontSize: 11.5, color: COLORS.textMuted, marginBottom: 4 }}>{label}</div>
      <div style={{ fontSize: 19, fontWeight: 800, color, fontVariantNumeric: "tabular-nums" }}><CountUp value={value} /></div>
      {sub && <div style={{ fontSize: 11.5, color: COLORS.textMuted, marginTop: 3 }}>{sub}</div>}
    </div>
  );
}

